 5: namespace App\Http\Controllers\Api\V1;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Models\Customer;
 9: use App\Models\ReturnRequestItem;
10: use App\Models\SupplierDelivery;
11: use App\Models\SupplierInvoice;
12: use App\Models\SupplierUser;
13: use App\Models\User;
14: use Illuminate\Http\Request;
15: use Illuminate\Support\Facades\Storage;
16: use Symfony\Component\HttpFoundation\StreamedResponse;
17: 
18: class AttachmentController extends Controller
19: {
20:     public function returnFile(Request $request, int $returnItem, int $attachment): StreamedResponse
21:     {
22:         $actor = $request->user();
23:         $query = ReturnRequestItem::query();
24:         if ($actor instanceof Customer) {
25:             $query->whereHas('returnRequest', fn ($q) => $q->where('customer_id', $actor->id));
26:         } else {
27:             abort_unless($actor instanceof User && $actor->can('returns.view'), 403);
28:         }
29:         $item = $query->findOrFail($returnItem);
30: 
31:         return $this->download(($item->attachments ?? [])[$attachment] ?? null);
32:     }
33: 
34:     public function invoice(Request $request, int $invoice): StreamedResponse
35:     {
36:         $actor = $request->user();
37:         $query = SupplierInvoice::query();
38:         if ($actor instanceof SupplierUser) {
39:             $query->where('supplier_id', $actor->supplier_id)->where('status', '!=', 'draft');
40:         } else {
41:             abort_unless($actor instanceof User && $actor->can('purchases.view'), 403);
42:         }
43: 
44:         return $this->download($query->findOrFail($invoice)->attachment_path);
45:     }
46: 
47:     public function delivery(Request $request, int $delivery): StreamedResponse
48:     {
49:         $actor = $request->user();
50:         $query = SupplierDelivery::query();
51:         if ($actor instanceof SupplierUser) {
52:             $query->where('supplier_id', $actor->supplier_id);
53:         } else {
54:             abort_unless($actor instanceof User && $actor->can('purchases.view'), 403);
55:         }
56: 
57:         return $this->download($query->findOrFail($delivery)->invoice_file_path);
58:     }
59: 
60:     private function download(?string $path): StreamedResponse
61:     {
62:         abort_if($path === null || ! Storage::disk('local')->exists($path), 404);
63: 
64:         return Storage::disk('local')->download($path, basename($path), ['X-Content-Type-Options' => 'nosniff', 'Cache-Control' => 'private, no-store']);
65:     }
66: } 1: <?php
