 9: final class DiscreteQuantity
10: {
11:     public static function assert(mixed $qty, bool $allowZero = false): void
12:     {
13:         if (! is_numeric($qty) || ! is_finite((float) $qty)
14:             || (float) $qty < ($allowZero ? 0 : 1) || (float) $qty > 99999999
15:             || abs((float) $qty - round((float) $qty)) > 1e-9) {
16:             throw new BusinessException('الكمية يجب أن تكون عددًا صحيحًا ضمن الحد المسموح.');
17:         }
18:     }
19: } 1: <?php
