 5: namespace App\Services;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use Illuminate\Database\Eloquent\Model;
 9: use Illuminate\Support\Facades\DB;
10: 
11: class OperationIdempotencyService
12: {
13:     public function run(string $operation, Model $actor, ?string $key, array $payload, callable $execute): Model
14:     {
15:         if ($key === null || ! preg_match('/\A[A-Za-z0-9._:-]{1,128}\z/', $key)) {
16:             throw new BusinessException('ترويسة Idempotency-Key مطلوبة (حتى 128 حرفًا إنجليزيًا أو رقمًا).');
17:         }
18:         $scope = ['operation' => $operation, 'actor_type' => $actor->getMorphClass(), 'actor_id' => $actor->getKey(), 'key' => $key];
19:         $hash = IdempotencyFingerprint::hash($payload);
20: 
21:         return DB::transaction(function () use ($scope, $hash, $execute): Model {
22:             $inserted = DB::table('operation_idempotency_keys')->insertOrIgnore([
23:                 ...$scope, 'request_hash' => $hash, 'created_at' => now(),
24:             ]);
25:             $record = DB::table('operation_idempotency_keys')->where($scope)->lockForUpdate()->first();
26:             if (! $inserted) {
27:                 if (! hash_equals($record->request_hash, $hash)) {
28:                     throw new BusinessException('مفتاح عدم التكرار مستخدم مع بيانات مختلفة.', [], 409);
29:                 }
30:                 $result = $record->result_type::query()->find($record->result_id);
31:                 if ($result === null) {
32:                     throw new BusinessException('العملية سبق تنفيذها ثم أزيل مستندها؛ استخدم عملية جديدة.', [], 409);
33:                 }
34: 
35:                 return $result;
36:             }
37:             $result = $execute();
38:             DB::table('operation_idempotency_keys')->where($scope)->update([
39:                 'result_type' => $result::class, 'result_id' => $result->getKey(),
40:             ]);
41: 
42:             return $result;
43:         }, 3);
44:     }
45: } 1: <?php
