 7: use Illuminate\Http\UploadedFile;
 8: use Illuminate\Support\Facades\DB;
 9: use Illuminate\Support\Facades\Storage;
10: use RuntimeException;
11: use Throwable;
12: 
13: class PrivateAttachments
14: {
15:     private array $stored = [];
16: 
17:     public static function transaction(callable $callback): mixed
18:     {
19:         $files = new self;
20:         try {
21:             return DB::transaction(fn () => $callback($files));
22:         } catch (Throwable $exception) {
23:             Storage::disk('local')->delete($files->stored);
24:             throw $exception;
25:         }
26:     }
27: 
28:     public function store(UploadedFile $file, string $directory): string
29:     {
30:         $path = $file->store($directory, 'local');
31:         if ($path === false) {
32:             throw new RuntimeException('تعذر حفظ المرفق؛ لم يتم تسجيل العملية.');
33:         }
34:         $this->stored[] = $path;
35: 
36:         return $path;
37:     }
38: } 1: <?php
