 7: use App\Enums\CustomerStatus;
 8: use App\Exceptions\BusinessException;
 9: use App\Models\Customer;
10: use App\Models\CustomerWalletTransaction;
11: use Illuminate\Support\Facades\DB;
12: 
13: class WalletService
14: {
15:     public function record(int $customerId, float $amount, string $type, string $referenceType, int $referenceId, ?int $createdBy = null): CustomerWalletTransaction
16:     {
17:         return DB::transaction(function () use ($customerId, $amount, $type, $referenceType, $referenceId, $createdBy): CustomerWalletTransaction {
18:             $customer = Customer::query()->lockForUpdate()->findOrFail($customerId);
19:             if ($type === 'checkout_payment' && $customer->status !== CustomerStatus::Approved) {
20:                 throw new BusinessException('الدفع بالمحفظة يتطلب حساب عميل نشطًا.');
21:             }
22:             if (CustomerWalletTransaction::query()->where('reference_type', $referenceType)->where('reference_id', $referenceId)->where('type', $type)->exists()) {
23:                 throw new BusinessException('حركة المحفظة مسجلة سابقًا.', [], 409);
24:             }
25:             $amountCents = (int) round($amount * 100);
26:             $balanceCents = (int) round((float) $customer->wallet_balance * 100) + $amountCents;
27:             if ($balanceCents < 0) {
28:                 throw new BusinessException('رصيد المحفظة لا يكفي قيمة الطلب كاملة.');
29:             }
30:             if ($balanceCents > 999999999999) {
31:                 throw new BusinessException('رصيد المحفظة يتجاوز الحد المسموح.');
32:             }
33:             $entry = CustomerWalletTransaction::create([
34:                 'customer_id' => $customerId, 'type' => $type, 'amount' => $amountCents / 100,
35:                 'balance_after' => $balanceCents / 100, 'reference_type' => $referenceType,
36:                 'reference_id' => $referenceId, 'created_by' => $createdBy,
37:             ]);
38:             $customer->update(['wallet_balance' => $balanceCents / 100]);
39: 
40:             return $entry;
41:         });
42:     }
43: }1: <?php
