145:     private function race(array $jobs, array $expected = ['OK', 'OK']): void
146:     {
147:         $barrier = tempnam(sys_get_temp_dir(), 'inventory-race-');
148:         unlink($barrier);
149:         $db = config('database.connections.pgsql');
150:         $environment = ['APP_ENV' => 'testing', 'DB_CONNECTION' => 'pgsql', 'DB_DATABASE' => $db['database'],
151:             'DB_HOST' => $db['host'], 'DB_PORT' => (string) $db['port'], 'DB_USERNAME' => $db['username'],
152:             'DB_PASSWORD' => $db['password'], 'DB_URL' => '', 'CACHE_STORE' => 'array', 'QUEUE_CONNECTION' => 'sync',
153:             'INVENTORY_START_FILE' => $barrier];
154:         $processes = [];
155:         try {
156:             foreach ($jobs as $operation) {
157:                 $script = <<<'PHP'
158: require 'vendor/autoload.php';
159: $app = require 'bootstrap/app.php';
160: $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
161: Illuminate\Support\Facades\DB::statement("SET lock_timeout = '7s'");
162: echo "READY\n";
163: $deadline = microtime(true) + 12;
164: while (!is_file(getenv('INVENTORY_START_FILE'))) {
165:     if (microtime(true) > $deadline) { exit(4); }
166:     usleep(10000);
167: }
168: try {
169: PHP;
170:                 $script .= $operation;
171:                 $script .= <<<'PHP'
172: echo "OK\n";
173: } catch (App\Exceptions\BusinessException $exception) {
174:     echo "REJECTED\n";
175: } catch (Throwable $exception) {
176:     fwrite(STDERR, get_class($exception).': '.$exception->getMessage());
177:     exit(3);
178: }
179: PHP;
180:                 $process = new Process([PHP_BINARY, '-r', $script], base_path(), $environment, timeout: 15);
181:                 $process->start();
182:                 $processes[] = $process;
183:             }
184:             foreach ($processes as $process) {
185:                 $this->assertTrue($process->waitUntil(fn ($type, $output) => str_contains($output, 'READY')), $process->getErrorOutput());
186:             }
187:             touch($barrier);
188:             $results = [];
189:             foreach ($processes as $process) {
190:                 $process->wait();
191:                 $this->assertTrue($process->isSuccessful(), $process->getErrorOutput());
192:                 $results[] = trim(str_replace('READY', '', $process->getOutput()));
193:             }
194:             $this->assertEqualsCanonicalizing($expected, $results);
195:         } finally {
196:             foreach ($processes as $process) {
197:                 if ($process->isRunning()) {
198:                     $process->stop();
199:                 }
200:             }
201:             foreach ([$barrier, $barrier.'.left', $barrier.'.right', $barrier.'.stale'] as $path) {
202:                 if (is_file($path)) {
203:                     unlink($path);
204:                 }
205:             }
