414:     public function test_wallet_ledger_is_immutable_and_balance_cannot_become_negative(): void
415:     {
416:         $return = $this->receiveReturn($this->pending($this->order()));
417:         app(ReturnService::class)->refund($return, $this->admin, ['refund_method' => 'wallet']);
418:         $entry = CustomerWalletTransaction::firstOrFail();
419:         foreach (['update', 'delete', 'negative_balance', 'duplicate_reference'] as $operation) {
420:             try {
421:                 DB::transaction(function () use ($operation, $entry, $return): void {
422:                     if ($operation === 'update') {
423:                         CustomerWalletTransaction::whereKey($entry->id)->update(['amount' => 999]);
424:                     } elseif ($operation === 'delete') {
425:                         CustomerWalletTransaction::whereKey($entry->id)->delete();
426:                     } elseif ($operation === 'negative_balance') {
427:                         Customer::whereKey($return->customer_id)->update(['wallet_balance' => -1]);
428:                     } else {
429:                         CustomerWalletTransaction::create(collect($entry->getAttributes())->except('id')->all());
430:                     }
431:                 });
432:                 $this->fail('Wallet ledger safeguards must reject '.$operation);
433:             } catch (QueryException $exception) {
434:                 $this->assertContains($exception->errorInfo[0], ['P0001', '23514', '23505']);
435:             }
436:         }
437:         $this->assertSame('100.00', $entry->fresh()->amount);
438:         $this->assertSame('100.00', Customer::findOrFail($return->customer_id)->wallet_balance);
439:         $this->assertDatabaseCount('customer_wallet_transactions', 1);
440:     }
