  7: use App\Http\Controllers\Controller;
  8: use App\Http\Requests\Admin\Procurement\PurchaseOrderRequest;
  9: use App\Http\Requests\Admin\Procurement\ReceivePurchaseOrderRequest;
 10: use App\Http\Resources\Admin\PurchaseOrderResource;
 11: use App\Models\PurchaseOrder;
 12: use App\Models\User;
 13: use App\Services\ProcurementService;
 14: use App\Services\SearchTerm;
 15: use Illuminate\Http\JsonResponse;
 16: use Illuminate\Http\Request;
 17: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 18: use Illuminate\Routing\Controllers\HasMiddleware;
 19: use Illuminate\Routing\Controllers\Middleware;
 20: 
 21: /**
 22:  * أوامر الشراء للموردين: إنشاء/اعتماد/إرسال/إلغاء + استلام مخزني
 23:  * يحدّث متوسط التكلفة المرجح (ProcurementService::receivePurchaseOrder).
 24:  */
 25: class PurchaseOrderController extends Controller implements HasMiddleware
 26: {
 27:     public static function middleware(): array
 28:     {
 29:         return [
 30:             new Middleware('can:purchases.view', only: ['index', 'show']),
 31:             new Middleware('can:purchases.create', only: ['store']),
 32:             new Middleware('can:purchases.update', only: ['update', 'send', 'cancel']),
 33:             new Middleware('can:purchases.approve', only: ['approve']),
 34:             new Middleware('can:purchases.receive', only: ['receive', 'closeShort']),
 35:             new Middleware('can:purchases.delete', only: ['destroy']),
 36:         ];
 37:     }
 38: 
 39:     public function __construct(protected ProcurementService $procurement) {}
 40: 
 41:     public function index(Request $request): AnonymousResourceCollection
 42:     {
 43:         $search = trim((string) $request->query('search', ''));
 44:         $orders = PurchaseOrder::query()
 45:             ->with(['supplier:id,code,name', 'branch:id,name'])
 46:             ->when($request->query('status'), fn ($q, $status) => $q->where('status', $status))
 47:             ->when($request->query('supplier_id'), fn ($q, $id) => $q->where('supplier_id', (int) $id))
 48:             ->when($request->query('branch_id'), fn ($q, $id) => $q->where('branch_id', (int) $id))
 49:             ->when($search !== '', fn ($q) => $q->where('po_number', 'ilike', SearchTerm::pattern($search)))
 50:             ->latest('id')
 51:             ->paginate(20);
 52: 
 53:         return PurchaseOrderResource::collection($orders);
 54:     }
 55: 
 56:     public function store(PurchaseOrderRequest $request): JsonResponse
 57:     {
 58:         /** @var User $admin */
 59:         $admin = $request->user();
 60:         $po = $this->procurement->createPurchaseOrder($request->validated(), $admin);
 61:         $po->load(['supplier:id,code,name', 'branch:id,name', 'items.variant']);
 62: 
 63:         return PurchaseOrderResource::make($po)->response()->setStatusCode(201);
 64:     }
 65: 
 66:     public function show(PurchaseOrder $purchaseOrder): PurchaseOrderResource
 67:     {
 68:         return PurchaseOrderResource::make($purchaseOrder->load([
 69:             'supplier:id,code,name', 'branch:id,name', 'items.variant', 'deliveries.items.variant',
 70:         ]));
 71:     }
 72: 
 73:     public function update(PurchaseOrderRequest $request, PurchaseOrder $purchaseOrder): PurchaseOrderResource
 74:     {
 75:         $po = $this->procurement->updatePurchaseOrder($purchaseOrder, $request->validated());
 76:         $po->load(['supplier:id,code,name', 'branch:id,name', 'items.variant']);
 77: 
 78:         return PurchaseOrderResource::make($po);
 79:     }
 80: 
 81:     public function destroy(PurchaseOrder $purchaseOrder): JsonResponse
 82:     {
 83:         $this->procurement->deletePurchaseOrder($purchaseOrder);
 84: 
 85:         return response()->json(['message' => 'تم حذف أمر الشراء.']);
 86:     }
 87: 
 88:     public function approve(Request $request, PurchaseOrder $purchaseOrder): PurchaseOrderResource
 89:     {
 90:         /** @var User $admin */
 91:         $admin = $request->user();
 92: 
 93:         return PurchaseOrderResource::make($this->procurement->approvePurchaseOrder($purchaseOrder, $admin));
 94:     }
 95: 
 96:     public function send(PurchaseOrder $purchaseOrder): PurchaseOrderResource
 97:     {
 98:         return PurchaseOrderResource::make($this->procurement->sendPurchaseOrder($purchaseOrder));
 99:     }
100: 
101:     public function cancel(PurchaseOrder $purchaseOrder): PurchaseOrderResource
102:     {
103:         return PurchaseOrderResource::make($this->procurement->cancelPurchaseOrder($purchaseOrder));
104:     }
105: 
106:     public function closeShort(PurchaseOrder $purchaseOrder): PurchaseOrderResource
107:     {
108:         return PurchaseOrderResource::make($this->procurement->closeShort($purchaseOrder));
109:     }
110: 
111:     /** استلام بضاعة (كلي/جزئي) — يحدّث متوسط التكلفة ويغذي المخزون. */
112:     public function receive(ReceivePurchaseOrderRequest $request, PurchaseOrder $purchaseOrder): PurchaseOrderResource
113:     {
114:         /** @var User $admin */
115:         $admin = $request->user();
116:         $po = $this->procurement->receivePurchaseOrder(
117:             $purchaseOrder,
118:             $request->validated('items'),
119:             $request->validated('location_id') !== null ? (int) $request->validated('location_id') : null,
120:             $request->validated('supplier_delivery_id') !== null ? (int) $request->validated('supplier_delivery_id') : null,
121:             $admin->id,
122:             $request->header('Idempotency-Key'),
123:         );
124:         $po->load(['supplier:id,code,name', 'branch:id,name', 'items.variant']);
125: 
126:         return PurchaseOrderResource::make($po);
127:     }
