19: 
20: /**
21:  * دفعات الموردين: إنشاؤها يخفض رصيد المورد ويحدّث فاتورتها، وحذفها
22:  * يعكس الأثر كاملًا — عبر SupplierFinanceService فقط.
23:  */
24: class SupplierPaymentController extends Controller implements HasMiddleware
25: {
26:     public static function middleware(): array
27:     {
28:         return [
29:             new Middleware('can:purchases.view', only: ['index', 'show']),
30:             new Middleware('can:supplier_payments.create', only: ['store']),
31:             new Middleware('can:supplier_payments.update', only: ['update']),
32:             new Middleware('can:supplier_payments.delete', only: ['destroy']),
33:         ];
34:     }
35: 
36:     public function __construct(protected SupplierFinanceService $finance) {}
37: 
38:     public function index(Request $request): AnonymousResourceCollection
39:     {
40:         $payments = SupplierPayment::query()
41:             ->with(['invoice:id,invoice_number,supplier_invoice_no'])
42:             ->when($request->query('supplier_id'), fn ($q, $id) => $q->where('supplier_id', (int) $id))
43:             ->when($request->query('supplier_invoice_id'), fn ($q, $id) => $q->where('supplier_invoice_id', (int) $id))
44:             ->when($request->query('from_date'), fn ($q, $date) => $q->where('payment_date', '>=', $date))
45:             ->when($request->query('to_date'), fn ($q, $date) => $q->where('payment_date', '<=', $date))
46:             ->latest('id')
47:             ->paginate(20);
48: 
49:         return SupplierPaymentResource::collection($payments);
50:     }
51: 
52:     public function store(SupplierPaymentRequest $request): JsonResponse
53:     {
54:         /** @var User $admin */
55:         $admin = $request->user();
56:         $payment = $this->finance->createPayment($request->validated(), $admin, $request->header('Idempotency-Key'));
57:         $payment->load(['invoice:id,invoice_number,supplier_invoice_no']);
58: 
59:         return SupplierPaymentResource::make($payment)->response()->setStatusCode(201);
60:     }
61: 
62:     public function show(SupplierPayment $supplierPayment): SupplierPaymentResource
63:     {
64:         return SupplierPaymentResource::make($supplierPayment->load(['invoice:id,invoice_number,supplier_invoice_no']));
65:     }
66: 
67:     public function update(UpdateSupplierPaymentRequest $request, SupplierPayment $supplierPayment): SupplierPaymentResource
68:     {
69:         $supplierPayment = $this->finance->updatePayment($supplierPayment, $request->validated());
70: 
71:         return SupplierPaymentResource::make($supplierPayment->fresh(['invoice:id,invoice_number,supplier_invoice_no']));
72:     }
73: 
74:     public function destroy(SupplierPayment $supplierPayment): JsonResponse
75:     {
76:         $this->finance->deletePayment($supplierPayment);
77: 
78:         return response()->json(['message' => 'تم حذف الدفعة وعكس أثرها على الرصيد والفاتورة.']);
79:     }
80: } 1: <?php
