16: /**
17:  * دخول بوابة المورد: إيميل/كلمة مرور من supplier_users، بشرط حساب نشط
18:  * ومورد نشط — ثم توكن Sanctum باسم supplier-token.
19:  */
20: class AuthController extends Controller
21: {
22:     public function login(LoginRequest $request): JsonResponse
23:     {
24:         $user = SupplierUser::query()->where('email', $request->validated('email'))->first();
25: 
26:         if ($user === null || ! Hash::check($request->validated('password'), $user->password)) {
27:             throw ValidationException::withMessages([
28:                 'email' => ['بيانات الدخول غير صحيحة.'],
29:             ]);
30:         }
31:         if (! $user->is_active) {
32:             throw ValidationException::withMessages([
33:                 'email' => ['حساب المورد هذا غير نشط؛ تواصل مع الإدارة.'],
34:             ]);
35:         }
36:         $supplier = $user->supplier;
37:         if ($supplier === null || ! $supplier->is_active) {
38:             throw ValidationException::withMessages([
39:                 'email' => ['المورد التابع له هذا الحساب غير نشط حاليًا.'],
40:             ]);
41:         }
42: 
43:         return response()->json([
44:             'token' => $user->createToken('supplier-token')->plainTextToken,
45:             'user' => SupplierUserResource::make($user),
46:             'supplier' => [
47:                 'id' => $supplier->id,
48:                 'code' => $supplier->code,
49:                 'name' => $supplier->name,
50:                 'company_name' => $supplier->company_name,
51:             ],
52:         ]);
53:     }
54: 
55:     public function logout(Request $request): JsonResponse
56:     {
57:         /** @var SupplierUser $user */
58:         $user = $request->user();
59:         $user->currentAccessToken()?->delete();
60: 
61:         return response()->json(['message' => 'تم تسجيل الخروج.']);
62:     }
63: } 1: <?php
