 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Supplier\Delivery\StoreDeliveryRequest;
 9: use App\Http\Resources\Supplier\DeliveryResource;
10: use App\Models\PurchaseOrder;
11: use App\Models\SupplierDelivery;
12: use App\Models\SupplierUser;
13: use App\Services\ProcurementService;
14: use Illuminate\Http\JsonResponse;
15: use Illuminate\Http\Request;
16: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
17: 
18: /**
19:  * إشعارات توريد المورد (ASN): تسجيل شحنة جزئية/كلية مقابل أمر شرائه
20:  * مع فاتورة مبدئية — ويستلمها المخزن لاحقًا من إدارة أوامر الشراء.
21:  */
22: class DeliveryController extends Controller
23: {
24:     public function __construct(protected ProcurementService $procurement) {}
25: 
26:     public function store(StoreDeliveryRequest $request, int $purchaseOrder): JsonResponse
27:     {
28:         /** @var SupplierUser $user */
29:         $user = $request->user();
30:         $order = PurchaseOrder::query()
31:             ->where('supplier_id', $user->supplier_id)
32:             ->findOrFail($purchaseOrder);
33: 
34:         $delivery = $this->procurement->createSupplierDelivery(
35:             $order,
36:             $user,
37:             $request->safe()->except('invoice_file'),
38:             $request->file('invoice_file'),
39:             $request->header('Idempotency-Key'),
40:         );
41:         $delivery->load(['items.variant']);
42: 
43:         return DeliveryResource::make($delivery)->response()->setStatusCode(201);
44:     }
45: 
46:     public function index(Request $request): AnonymousResourceCollection
47:     {
48:         /** @var SupplierUser $user */
49:         $user = $request->user();
50:         $deliveries = SupplierDelivery::query()
51:             ->where('supplier_id', $user->supplier_id)
52:             ->with(['items.variant'])
53:             ->when($request->query('purchase_order_id'), fn ($q, $id) => $q->where('purchase_order_id', (int) $id))
54:             ->when($request->query('status'), fn ($q, $status) => $q->where('status', $status))
55:             ->latest('id')
56:             ->paginate(20);
57: 
58:         return DeliveryResource::collection($deliveries);
59:     }
60: 
61:     public function show(Request $request, int $delivery): DeliveryResource
62:     {
63:         /** @var SupplierUser $user */
64:         $user = $request->user();
65:         $record = SupplierDelivery::query()
66:             ->where('supplier_id', $user->supplier_id)
67:             ->with(['items.variant'])
68:             ->findOrFail($delivery);
69: 
70:         return DeliveryResource::make($record);
71:     }
72: } 1: <?php
