 5: namespace App\Http\Controllers\Api\V1\Supplier;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Supplier\PurchaseOrder\RequestChangeRequest;
 9: use App\Http\Resources\Supplier\PurchaseOrderResource;
10: use App\Models\PurchaseOrder;
11: use App\Models\SupplierUser;
12: use App\Services\ProcurementService;
13: use Illuminate\Database\Eloquent\Builder;
14: use Illuminate\Http\Request;
15: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
16: 
17: /**
18:  * أوامر شراء المورد في بوابته — القاعدة الأمنية الأولى:
19:  * كل استعلام يبدأ بـ where('supplier_id', مورد صاحب التوكن)، فأمر مورد
20:  * آخر غير موجود أصلًا (404) ولا يظهر في أي قائمة.
21:  */
22: class PurchaseOrderController extends Controller
23: {
24:     public function __construct(protected ProcurementService $procurement) {}
25: 
26:     public function index(Request $request): AnonymousResourceCollection
27:     {
28:         /** @var SupplierUser $user */
29:         $user = $request->user();
30:         $orders = $this->scoped($user)
31:             ->with(['branch:id,name', 'items.variant'])
32:             ->when($request->query('status'), fn ($q, $status) => $q->where('status', $status))
33:             ->latest('id')
34:             ->paginate(20);
35: 
36:         return PurchaseOrderResource::collection($orders);
37:     }
38: 
39:     public function show(Request $request, int $purchaseOrder): PurchaseOrderResource
40:     {
41:         /** @var SupplierUser $user */
42:         $user = $request->user();
43:         $order = $this->scoped($user)
44:             ->with(['branch:id,name', 'items.variant', 'deliveries.items.variant'])
45:             ->findOrFail($purchaseOrder);
46: 
47:         return PurchaseOrderResource::make($order);
48:     }
49: 
50:     /** قبول أمر الشراء وتأكيد الالتزام بالتوريد: sent_to_supplier ← supplier_accepted. */
51:     public function accept(Request $request, int $purchaseOrder): PurchaseOrderResource
52:     {
53:         /** @var SupplierUser $user */
54:         $user = $request->user();
55:         $order = $this->scoped($user)->findOrFail($purchaseOrder);
56: 
57:         return PurchaseOrderResource::make($this->procurement->supplierAccept($order, $user));
58:     }
59: 
60:     /** طلب تعديل أسعار/كميات/موعد مع ملاحظات للإدارة: ← change_requested. */
61:     public function requestChange(RequestChangeRequest $request, int $purchaseOrder): PurchaseOrderResource
62:     {
63:         /** @var SupplierUser $user */
64:         $user = $request->user();
65:         $order = $this->scoped($user)->findOrFail($purchaseOrder);
66: 
67:         return PurchaseOrderResource::make(
68:             $this->procurement->supplierRequestChange($order, $user, $request->validated('notes'))
69:         );
70:     }
71: 
72:     /** استعلامات البوابة كلها تبدأ من نطاق مورد صاحب التوكن. */
73:     private function scoped(SupplierUser $user): Builder
74:     {
75:         return PurchaseOrder::query()->where('supplier_id', $user->supplier_id)
76:             ->where('status', '!=', 'draft');
77:     }
78: } 1: <?php
