 7: use Closure;
 8: use Illuminate\Http\Request;
 9: use Symfony\Component\HttpFoundation\Response;
10: 
11: class ProtectStorefrontCaching
12: {
13:     public function handle(Request $request, Closure $next): Response
14:     {
15:         $response = $next($request);
16:         $response->setVary('Authorization', false);
17:         if ($request->bearerToken() !== null || auth('sanctum')->check()) {
18:             $response->headers->set('Cache-Control', 'private, no-store');
19:         }
20: 
21:         return $response;
22:     }
23: } 1: <?php
