 5: namespace App\Http\Requests\Store\Return;
 6: 
 7: use App\Enums\RefundMethod;
 8: use Illuminate\Foundation\Http\FormRequest;
 9: use Illuminate\Validation\Rule;
10: 
11: /** تقديم طلب إرجاع من حساب العميل — مع صور عيوب اختيارية لكل بند. */
12: class StoreReturnRequest extends FormRequest
13: {
14:     public function authorize(): bool
15:     {
16:         return true;
17:     }
18: 
19:     /**
20:      * @return array<string, mixed>
21:      */
22:     public function rules(): array
23:     {
24:         return [
25:             'order_id' => ['required', 'integer', 'exists:orders,id'],
26:             'reason' => ['required', 'string', 'max:2000'],
27:             'refund_method' => ['nullable', Rule::in(array_column(RefundMethod::cases(), 'value'))],
28:             'items' => ['required', 'array', 'min:1', 'max:50'],
29:             'items.*.order_item_id' => ['required', 'integer', 'distinct'],
30:             'items.*.requested_qty' => ['required', 'integer', 'gt:0', 'max:99999999'],
31:             'items.*.item_reason' => ['nullable', 'string', 'max:255'],
32:             'items.*.attachments' => ['nullable', 'array', 'max:5'],
33:             'items.*.attachments.*' => ['file', 'image', 'mimes:jpg,jpeg,png,webp', 'max:5120'],
34:         ];
35:     }
36: 
37:     /**
38:      * الحمولة الجاهزة للخدمة: البيانات المتحقق منها + ملفات كل بند.
39:      *
40:      * @return array<string, mixed>
41:      */
42:     public function payload(): array
43:     {
44:         $data = $this->validated();
45:         foreach (array_keys($data['items'] ?? []) as $i) {
46:             $files = $this->file("items.{$i}.attachments");
47:             $data['items'][$i]['attachments'] = is_array($files) ? $files : ($files !== null ? [$files] : []);
48:         }
49: 
50:         return $data;
51:     }
52: } 1: <?php
