 27: /**
 28:  * خدمة المشتريات — دورة الشراء كاملة:
 29:  * طلب شراء داخلي (فرع) ← اعتماد ← أمر شراء لمورد ← إرسال ← قبول/طلب تعديل
 30:  * من بوابة المورد ← إشعارات توريد (ASN) ← استلام مخزني.
 31:  *
 32:  * قلب المرحلة المحاسبي: الاستلام يحدّث متوسط التكلفة المرجح (WAC) للمتغير
 33:  * قبل تغذية المخزون، والحركات كلها عبر InventoryService::recordMovement:
 34:  *   NewAvg = (CurrentTotalOnHand × OldCost + ReceivedQty × PurchaseCost)
 35:  *            ÷ (CurrentTotalOnHand + ReceivedQty)
 36:  * حيث CurrentTotalOnHand = مجموع on_hand للمتغير في كل الفروع.
 37:  */
 38: class ProcurementService
 39: {
 40:     public function __construct(
 41:         protected InventoryService $inventory,
 42:         protected SettingService $settings,
 43:     ) {}
 44: 
 45:     // ================= طلبات الشراء الداخلية =================
 46: 
 47:     /**
 48:      * @param  array{branch_id: int, notes?: string|null, items: list<array{product_variant_id: int, requested_qty: float|int|string, notes?: string|null}>}  $data
 49:      */
 50:     public function createPurchaseRequest(array $data, User $requester): PurchaseRequest
 51:     {
 52:         return DB::transaction(function () use ($data, $requester): PurchaseRequest {
 53:             $pr = PurchaseRequest::create([
 54:                 'request_number' => $this->settings->generateNextNumber('purchase_request'),
 55:                 'branch_id' => (int) $data['branch_id'],
 56:                 'requested_by' => $requester->id,
 57:                 'status' => PurchaseRequestStatus::Draft,
 58:                 'notes' => $data['notes'] ?? null,
 59:             ]);
 60:             $this->syncRequestItems($pr, $data['items']);
 61: 
 62:             return $pr->fresh(['items']);
 63:         });
 64:     }
 65: 
 66:     /**
 67:      * @param  array{branch_id?: int, notes?: string|null, items?: list<array{product_variant_id: int, requested_qty: float|int|string, notes?: string|null}>}  $data
 68:      */
 69:     public function updatePurchaseRequest(PurchaseRequest $pr, array $data): PurchaseRequest
 70:     {
 71:         return DB::transaction(function () use ($pr, $data): PurchaseRequest {
 72:             $pr = PurchaseRequest::query()->lockForUpdate()->findOrFail($pr->id);
 73:             if ($pr->status !== PurchaseRequestStatus::Draft) {
 74:                 throw new BusinessException('لا يمكن تعديل طلب شراء إلا وهو مسودة.');
 75:             }
 76:             $pr->update(array_intersect_key($data, array_flip(['branch_id', 'notes'])));
 77:             if (isset($data['items'])) {
 78:                 $pr->items()->delete();
 79:                 $this->syncRequestItems($pr, $data['items']);
 80:             }
 81: 
 82:             return $pr->fresh(['items']);
 83:         });
 84:     }
 85: 
 86:     public function submitPurchaseRequest(PurchaseRequest $pr): PurchaseRequest
 87:     {
 88:         return $this->transitionRequest($pr, PurchaseRequestStatus::Draft, PurchaseRequestStatus::Pending, 'الإرسال');
 89:     }
 90: 
 91:     public function approvePurchaseRequest(PurchaseRequest $pr): PurchaseRequest
 92:     {
 93:         return $this->transitionRequest($pr, PurchaseRequestStatus::Pending, PurchaseRequestStatus::Approved, 'الاعتماد');
 94:     }
 95: 
 96:     public function rejectPurchaseRequest(PurchaseRequest $pr): PurchaseRequest
 97:     {
 98:         return $this->transitionRequest($pr, PurchaseRequestStatus::Pending, PurchaseRequestStatus::Rejected, 'الرفض');
 99:     }
