101:     private function transitionRequest(PurchaseRequest $pr, PurchaseRequestStatus $from, PurchaseRequestStatus $to, string $action): PurchaseRequest
102:     {
103:         return DB::transaction(function () use ($pr, $from, $to, $action): PurchaseRequest {
104:             $pr = PurchaseRequest::query()->lockForUpdate()->findOrFail($pr->id);
105:             if ($pr->status !== $from) {
106:                 throw new BusinessException("لا يمكن {$action} طلب شراء في حالة ({$pr->status->value}).");
107:             }
108:             $pr->update(['status' => $to]);
109: 
110:             return $pr->fresh(['items']);
111:         });
112:     }
