114:     /** @param list<array{product_variant_id: int, requested_qty: float|int|string, notes?: string|null}> $items */
115:     private function syncRequestItems(PurchaseRequest $pr, array $items): void
116:     {
117:         foreach ($items as $item) {
118:             DiscreteQuantity::assert($item['requested_qty']);
119:             $pr->items()->create([
120:                 'product_variant_id' => (int) $item['product_variant_id'],
121:                 'requested_qty' => (float) $item['requested_qty'],
122:                 'notes' => $item['notes'] ?? null,
123:             ]);
124:         }
125:     }
