127:     // ================= أوامر الشراء =================
128: 
129:     /**
130:      * إنشاء أمر شراء (مسودة). عند ربطه بطلب داخلي معتمد تُنسخ بنوده
131:      * افتراضيًا (بسعر تكلفة المتغير الحالية وضريبة صفر قابلة للتعديل)،
132:      * ويتحول الطلب إلى converted_to_po.
133:      *
134:      * @param  array{supplier_id: int, branch_id?: int|null, purchase_request_id?: int|null, expected_delivery_date?: string|null, discount_amount?: float|int|string|null, items?: list<array{product_variant_id: int, ordered_qty: float|int|string, unit_cost: float|int|string, tax_rate?: float|int|string|null}>}  $data
135:      */
136:     public function createPurchaseOrder(array $data, User $creator): PurchaseOrder
137:     {
138:         return DB::transaction(function () use ($data, $creator): PurchaseOrder {
139:             $pr = null;
140:             if (! empty($data['purchase_request_id'])) {
141:                 $pr = PurchaseRequest::query()->lockForUpdate()->find((int) $data['purchase_request_id']);
142:                 if ($pr === null) {
143:                     throw new BusinessException('طلب الشراء الداخلي المرتبط غير موجود.');
144:                 }
145:                 if ($pr->status !== PurchaseRequestStatus::Approved) {
146:                     throw new BusinessException('لا يمكن إنشاء أمر شراء إلا من طلب داخلي معتمد.');
147:                 }
148:                 $pr->load('items.variant');
149:             }
150: 
151:             $items = $data['items'] ?? [];
152:             if ($items === [] && $pr !== null) {
153:                 $items = $pr->items->map(fn ($item): array => [
154:                     'product_variant_id' => (int) $item->product_variant_id,
155:                     'ordered_qty' => (float) $item->requested_qty,
156:                     'unit_cost' => (float) ($item->variant?->cost_price ?? 0),
157:                     'tax_rate' => 0,
158:                 ])->all();
159:             }
160:             if ($items === []) {
161:                 throw new BusinessException('أمر الشراء يحتاج بندًا واحدًا على الأقل.');
162:             }
163: 
164:             $branchId = (int) ($data['branch_id'] ?? $pr?->branch_id ?? 0);
165:             if ($branchId <= 0) {
166:                 throw new BusinessException('حدد فرع/مخزن استلام أمر الشراء.');
167:             }
168: 
169:             if (! Supplier::query()->whereKey($data['supplier_id'])->where('is_active', true)->exists()
170:                 || ! Branch::query()->whereKey($branchId)->where('is_active', true)->exists()) {
171:                 throw new BusinessException('المورد وفرع الاستلام يجب أن يكونا نشطين.');
172:             }
173:             $po = PurchaseOrder::create([
174:                 'po_number' => $this->settings->generateNextNumber('purchase_order'),
175:                 'supplier_id' => (int) $data['supplier_id'],
176:                 'branch_id' => $branchId,
177:                 'purchase_request_id' => $pr?->id,
178:                 'status' => PurchaseOrderStatus::Draft,
179:                 'expected_delivery_date' => $data['expected_delivery_date'] ?? null,
180:                 'discount_amount' => (float) ($data['discount_amount'] ?? 0),
181:                 'created_by' => $creator->id,
182:             ]);
183:             $this->syncOrderItems($po, $items);
184:             $this->recalculateTotals($po);
185: 
186:             $pr?->update(['status' => PurchaseRequestStatus::ConvertedToPo]);
187: 
188:             return $po->fresh(['items']);
189:         });
190:     }
191: 
192:     /**
193:      * @param  array{supplier_id?: int, branch_id?: int, expected_delivery_date?: string|null, discount_amount?: float|int|string|null, items?: list<array{product_variant_id: int, ordered_qty: float|int|string, unit_cost: float|int|string, tax_rate?: float|int|string|null}>}  $data
194:      */
195:     public function updatePurchaseOrder(PurchaseOrder $po, array $data): PurchaseOrder
196:     {
197:         return DB::transaction(function () use ($po, $data): PurchaseOrder {
198:             $po = $this->lockOrder($po);
199:             if (! in_array($po->status, [PurchaseOrderStatus::Draft, PurchaseOrderStatus::ChangeRequested], true)) {
200:                 throw new BusinessException('لا يمكن تعديل أمر شراء إلا وهو مسودة أو بانتظار معالجة تعديلات المورد.');
201:             }
202:             if ($po->items()->where('received_qty', '>', 0)->exists()) {
203:                 throw new BusinessException('أمر شراء بدأ استلامه لا تُعدَّل بنوده.');
204:             }
205:             if ($po->deliveries()->exists()
206:                 && (isset($data['items'])
207:                     || (isset($data['supplier_id']) && (int) $data['supplier_id'] !== (int) $po->supplier_id)
208:                     || (isset($data['branch_id']) && (int) $data['branch_id'] !== (int) $po->branch_id))) {
209:                 throw new BusinessException('لا يمكن تغيير المورد أو الفرع أو البنود بعد تسجيل إشعار توريد.');
210:             }
211:             if (array_intersect(['supplier_id', 'branch_id', 'items', 'discount_amount', 'expected_delivery_date'], array_keys($data))) {
212:                 $data['approved_by'] = null;
213:             }
214:             if (isset($data['supplier_id']) && ! Supplier::query()->whereKey($data['supplier_id'])->where('is_active', true)->exists()) {
215:                 throw new BusinessException('المورد غير نشط.');
216:             }
217:             if (isset($data['branch_id']) && ! Branch::query()->whereKey($data['branch_id'])->where('is_active', true)->exists()) {
218:                 throw new BusinessException('فرع الاستلام غير نشط.');
219:             }
220:             $po->update(array_intersect_key($data, array_flip([
221:                 'supplier_id', 'branch_id', 'expected_delivery_date', 'discount_amount', 'approved_by',
222:             ])));
223:             if (isset($data['items'])) {
224:                 $po->items()->delete();
225:                 $this->syncOrderItems($po, $data['items']);
226:             }
227:             $this->recalculateTotals($po);
228: 
229:             return $po->fresh(['items']);
230:         });
231:     }
