233:     /** ختم الاعتماد الداخلي (approved_by) على مسودة — الإرسال خطوة مستقلة. */
234:     public function approvePurchaseOrder(PurchaseOrder $po, User $admin): PurchaseOrder
235:     {
236:         return DB::transaction(function () use ($po, $admin): PurchaseOrder {
237:             $po = $this->lockOrder($po);
238:             if (! in_array($po->status, [PurchaseOrderStatus::Draft, PurchaseOrderStatus::ChangeRequested], true)) {
239:                 throw new BusinessException('لا يمكن اعتماد أمر شراء إلا وهو مسودة أو بانتظار معالجة التعديلات.');
240:             }
241:             $po->update(['approved_by' => $admin->id]);
242: 
243:             return $po->fresh(['items']);
