247:     public function sendPurchaseOrder(PurchaseOrder $po): PurchaseOrder
248:     {
249:         return DB::transaction(function () use ($po): PurchaseOrder {
250:             $po = $this->lockOrder($po);
251:             if (! in_array($po->status, [PurchaseOrderStatus::Draft, PurchaseOrderStatus::ChangeRequested], true)) {
252:                 throw new BusinessException("لا يمكن إرسال أمر شراء في حالة ({$po->status->value}).");
253:             }
254:             if ($po->approved_by === null) {
255:                 throw new BusinessException('يجب اعتماد أمر الشراء قبل إرساله إلى المورد.');
256:             }
257:             if ($po->items()->count() === 0) {
258:                 throw new BusinessException('لا يمكن إرسال أمر شراء بلا بنود.');
259:             }
260:             $po->update(['status' => PurchaseOrderStatus::SentToSupplier, 'supplier_change_notes' => null]);
261: 
262:             return $po->fresh(['items']);
263:         });
264:     }
