266:     public function cancelPurchaseOrder(PurchaseOrder $po): PurchaseOrder
267:     {
268:         return DB::transaction(function () use ($po): PurchaseOrder {
269:             $po = $this->lockOrder($po);
270:             if ($po->items()->where('received_qty', '>', 0)->exists()) {
271:                 throw new BusinessException('لا يمكن إلغاء أمر شراء بدأ استلام بضاعته.');
272:             }
273:             if (! in_array($po->status, [
274:                 PurchaseOrderStatus::Draft, PurchaseOrderStatus::SentToSupplier,
275:                 PurchaseOrderStatus::SupplierAccepted, PurchaseOrderStatus::ChangeRequested,
276:             ], true)) {
277:                 throw new BusinessException("لا يمكن إلغاء أمر شراء في حالة ({$po->status->value}).");
278:             }
279:             $po->update(['status' => PurchaseOrderStatus::Cancelled]);
280:             $po->deliveries()->where('status', SupplierDeliveryStatus::PendingReceipt)->update(['status' => SupplierDeliveryStatus::Rejected]);
281:             if ($po->purchase_request_id !== null) {
282:                 PurchaseRequest::query()->whereKey($po->purchase_request_id)->where('status', PurchaseRequestStatus::ConvertedToPo)->update(['status' => PurchaseRequestStatus::Approved]);
283:             }
284: 
285:             return $po->fresh(['items']);
286:         });
287:     }
