289:     /** @param list<array{product_variant_id: int, ordered_qty: float|int|string, unit_cost: float|int|string, tax_rate?: float|int|string|null}> $items */
290:     private function syncOrderItems(PurchaseOrder $po, array $items): void
291:     {
292:         foreach ($items as $item) {
293:             DiscreteQuantity::assert($item['ordered_qty']);
294:             $qty = (float) $item['ordered_qty'];
295:             $cost = (float) $item['unit_cost'];
296:             $po->items()->create([
297:                 'product_variant_id' => (int) $item['product_variant_id'],
298:                 'ordered_qty' => $qty,
299:                 'unit_cost' => $cost,
300:                 'tax_rate' => (float) ($item['tax_rate'] ?? 0),
301:                 'line_total' => round($qty * $cost, 4),
302:             ]);
303:         }
304:     }
305: 
306:     /** إجماليات الرأس من البنود: subtotal وضرائب البنود والخصم والنهائي. */
307:     private function recalculateTotals(PurchaseOrder $po): void
308:     {
309:         $items = $po->items()->get();
310:         $subtotal = round((float) $items->sum(fn (PurchaseOrderItem $i): float => (float) $i->line_total), 2);
311:         $tax = round((float) $items->sum(fn (PurchaseOrderItem $i): float => (float) $i->line_total * (float) $i->tax_rate / 100), 2);
312:         if ((float) $po->discount_amount > $subtotal) {
313:             throw new BusinessException('خصم أمر الشراء لا يمكن أن يتجاوز مجموع البنود.');
314:         }
315:         $po->update([
316:             'subtotal' => $subtotal,
317:             'tax_amount' => $tax,
318:             'grand_total' => round($subtotal - (float) $po->discount_amount + $tax, 2),
319:         ]);
320:     }
321: 
322:     public function deletePurchaseOrder(PurchaseOrder $po): void
323:     {
324:         DB::transaction(function () use ($po): void {
325:             $po = $this->lockOrder($po);
326:             if (! in_array($po->status, [PurchaseOrderStatus::Draft, PurchaseOrderStatus::Cancelled], true)
327:                 || $po->deliveries()->exists() || $po->items()->where('received_qty', '>', 0)->exists()
328:                 || $po->invoices()->exists()) {
329:                 throw new BusinessException('لا يمكن حذف أمر شراء له استلام أو توريدات أو فواتير؛ احتفظ بالمستند للتدقيق.');
330:             }
331:             $po->delete();
332:         });
333:     }
