335:     public function closeShort(PurchaseOrder $po): PurchaseOrder
336:     {
337:         return DB::transaction(function () use ($po): PurchaseOrder {
338:             $po = $this->lockOrder($po);
339:             if ($po->status !== PurchaseOrderStatus::PartiallyReceived) {
340:                 throw new BusinessException('إغلاق النقص متاح لأمر مستلم جزئيًا فقط.');
341:             }
342:             $po->deliveries()->where('status', SupplierDeliveryStatus::PendingReceipt)->update(['status' => SupplierDeliveryStatus::Rejected]);
343:             $po->update(['status' => PurchaseOrderStatus::Completed]);
344: 
345:             return $po->fresh(['items']);
346:         });
347:     }
