349:     private function lockOrder(PurchaseOrder $po): PurchaseOrder
350:     {
351:         return PurchaseOrder::query()->lockForUpdate()->findOrFail($po->id);
352:     }
353: 
354:     // ================= الاستلام ومتوسط التكلفة =================
355: 
356:     /**
357:      * استلام بضاعة أمر شراء (كلي أو جزئي) + تحديث متوسط التكلفة المرجح
358:      * + تغذية المخزون — قلب المرحلة 10.
359:      *
360:      * عند ربط الاستلام بإشعار توريد (supplierDeliveryId) تُطابَق الكميات
361:      * مع بنوده وتُحدَّث حالته إلى received عند اكتمال استلام مشحوناته.
362:      *
363:      * @param  list<array{purchase_order_item_id: int, qty: float|int|string}>  $receivedItems
364:      */
365:     public function receivePurchaseOrder(PurchaseOrder $po, array $receivedItems, ?int $locationId = null, ?int $supplierDeliveryId = null, ?int $performedBy = null, ?string $idempotencyKey = null): PurchaseOrder
366:     {
367:         $actor = User::query()->findOrFail($performedBy ?? auth()->id());
368: 
369:         return app(OperationIdempotencyService::class)->run('purchase_receipt', $actor, $idempotencyKey,
370:             ['purchase_order_id' => $po->id, 'items' => $receivedItems, 'location_id' => $locationId, 'supplier_delivery_id' => $supplierDeliveryId],
371:             fn () => $this->executePurchaseReceipt($po, $receivedItems, $locationId, $supplierDeliveryId, $actor->id));
372:     }
373: 
374:     private function executePurchaseReceipt(PurchaseOrder $po, array $receivedItems, ?int $locationId, ?int $supplierDeliveryId, int $performedBy): PurchaseOrder
375:     {
376:         return DB::transaction(function () use ($po, $receivedItems, $locationId, $supplierDeliveryId, $performedBy): PurchaseOrder {
377:             $po = $this->lockOrder($po);
378:             if (! in_array($po->status, [
379:                 PurchaseOrderStatus::SentToSupplier,
380:                 PurchaseOrderStatus::SupplierAccepted,
381:                 PurchaseOrderStatus::PartiallyReceived,
382:             ], true)) {
383:                 throw new BusinessException("لا يمكن استلام بضاعة لأمر شراء في حالة ({$po->status->value}).");
384:             }
385: 
386:             if ($supplierDeliveryId === null && $po->deliveries()->where('status', SupplierDeliveryStatus::PendingReceipt)->exists()) {
387:                 throw new BusinessException('حدد إشعار التوريد المعلق عند الاستلام لمنع احتساب كمياته مرتين.');
388:             }
389:             $poItems = $po->items()->orderBy('product_variant_id')->orderBy('id')->lockForUpdate()->get()->keyBy('id');
390:             usort($receivedItems, fn (array $a, array $b): int => [($poItems->get((int) $a['purchase_order_item_id'])?->product_variant_id ?? 0), (int) $a['purchase_order_item_id']]
391:                 <=> [($poItems->get((int) $b['purchase_order_item_id'])?->product_variant_id ?? 0), (int) $b['purchase_order_item_id']]);
392:             $variants = ProductVariant::query()->whereIn('id', $poItems->pluck('product_variant_id'))->orderBy('id')->lockForUpdate()->get()->keyBy('id');
393:             $costFactor = (float) $po->subtotal > 0 ? max(0.0, 1 - (float) $po->discount_amount / (float) $po->subtotal) : 1.0;
394:             $delivery = null;
395:             $deliveryItems = collect();
396:             if ($supplierDeliveryId !== null) {
397:                 $delivery = SupplierDelivery::query()->lockForUpdate()
398:                     ->where('purchase_order_id', $po->id)
399:                     ->findOrFail($supplierDeliveryId);
400:                 if ($delivery->status !== SupplierDeliveryStatus::PendingReceipt) {
401:                     throw new BusinessException('إشعار التوريد هذا تمت معالجته من قبل.');
402:                 }
403:                 $deliveryItems = $delivery->items()->get()->keyBy('purchase_order_item_id');
404:             }
405: 
406:             foreach ($receivedItems as $itemData) {
407:                 $poItem = $poItems->get((int) $itemData['purchase_order_item_id']);
408:                 if ($poItem === null) {
409:                     throw new BusinessException('أحد بنود الاستلام لا يتبع أمر الشراء هذا.');
410:                 }
411:                 DiscreteQuantity::assert($itemData['qty']);
412:                 $qtyToReceive = (float) $itemData['qty'];
413:                 if ($qtyToReceive <= 0) {
414:                     continue;
415:                 }
416: 
417:                 $remainingQty = (float) $poItem->ordered_qty - (float) $poItem->received_qty;
418:                 if (round($qtyToReceive, 4) > round($remainingQty, 4)) {
419:                     throw new BusinessException("الكمية المستلمة ({$qtyToReceive}) أكبر من الكمية المتبقية في أمر الشراء ({$remainingQty}).");
420:                 }
421: 
422:                 $deliveryItem = null;
423:                 if ($delivery !== null) {
424:                     $deliveryItem = $deliveryItems->get($poItem->id);
425:                     if ($deliveryItem === null) {
426:                         throw new BusinessException('أحد بنود الاستلام غير موجود في إشعار التوريد المحدد.');
427:                     }
428:                     $shippedRemaining = (float) $deliveryItem->shipped_qty - (float) $deliveryItem->received_qty;
429:                     if (round($qtyToReceive, 4) > round($shippedRemaining, 4)) {
430:                         throw new BusinessException('الكمية المستلمة أكبر من المشحونة المتبقية في إشعار التوريد.');
431:                     }
432:                 }
433: 
434:                 // 1. المتغير مقفولًا لتحديث متوسط التكلفة بأمان
435:                 $variant = $variants->get($poItem->product_variant_id);
436:                 if ($variant === null) {
437:                     throw new BusinessException('متغير الصنف غير متاح للاستلام.');
438:                 }
439: 
440:                 // Includes damaged stock: it remains part of physical on_hand across all branches.
441:                 $currentTotalOnHand = (float) StockLevel::query()
442:                     ->where('product_variant_id', $variant->id)
443:                     ->sum('on_hand');
444:                 $oldCost = (float) $variant->cost_price;
445:                 $newUnitCost = round((float) $poItem->unit_cost * $costFactor, 4);
446: 
447:                 // معادلة المتوسط المرجح للتكلفة (WAC)
448:                 $safeCurrentStock = max(0.0, $currentTotalOnHand);
449:                 $newAverageCost = ($safeCurrentStock + $qtyToReceive) > 0
450:                     ? (($safeCurrentStock * $oldCost) + ($qtyToReceive * $newUnitCost)) / ($safeCurrentStock + $qtyToReceive)
451:                     : $newUnitCost;
452: 
453:                 $variant->update([
454:                     'cost_price' => round($newAverageCost, 4),
455:                     'last_cost_price' => $newUnitCost,
456:                 ]);
457: 
458:                 // 2. حركة إضافة للمخزون عبر InventoryService حصرًا
459:                 $this->inventory->recordMovement([
460:                     'product_variant_id' => $variant->id,
461:                     'branch_id' => (int) $po->branch_id,
462:                     'location_id' => $locationId,
463:                     'type' => StockMovementType::PurchaseReceipt,
464:                     'affected_bucket' => StockBucket::OnHand,
465:                     'quantity' => $qtyToReceive,
466:                     'unit_cost' => $newUnitCost,
467:                     'reference_type' => PurchaseOrder::class,
468:                     'reference_id' => $po->id,
469:                     'created_by' => $performedBy ?? auth()->id(),
470:                     'notes' => "استلام من أمر شراء رقم {$po->po_number}",
471:                 ]);
472: 
473:                 // 3. تحديث المستلم في بند الأمر (وبند إشعار التوريد عند الربط)
474:                 $poItem->increment('received_qty', $qtyToReceive);
475:                 $deliveryItem?->increment('received_qty', $qtyToReceive);
476:             }
477: 
478:             if ($delivery !== null) {
479:                 $allDeliveryReceived = $delivery->items()->get()
480:                     ->every(fn (SupplierDeliveryItem $i): bool => (float) $i->received_qty >= (float) $i->shipped_qty);
481:                 if ($allDeliveryReceived) {
482:                     $delivery->update(['status' => SupplierDeliveryStatus::Received]);
483:                 }
484:             }
485: 
486:             // 4. حالة الأمر: مكتمل عند استلام كل بنوده، وإلا جزئي
487:             $po->load('items');
488:             $allCompleted = $po->items->every(fn (PurchaseOrderItem $i): bool => (float) $i->received_qty >= (float) $i->ordered_qty);
489:             $po->update(['status' => $allCompleted ? PurchaseOrderStatus::Completed : PurchaseOrderStatus::PartiallyReceived]);
490: 
491:             return $po->fresh(['items.variant']);
492:         });
493:     }
