495:     // ================= بوابة المورد =================
496: 
497:     /** قبول المورد لأمر شراء مُرسل إليه (نطاق المورد يُفرض هنا أيضًا). */
498:     public function supplierAccept(PurchaseOrder $po, SupplierUser $user): PurchaseOrder
499:     {
500:         $this->assertOwnsOrder($po, $user);
501: 
502:         return DB::transaction(function () use ($po, $user): PurchaseOrder {
503:             $po = $this->lockOrder($po);
504:             $this->assertOwnsOrder($po, $user);
505:             if ($po->status !== PurchaseOrderStatus::SentToSupplier) {
506:                 throw new BusinessException("لا يمكن قبول أمر شراء في حالة ({$po->status->value}).");
507:             }
508:             $po->update(['status' => PurchaseOrderStatus::SupplierAccepted]);
509: 
510:             return $po->fresh(['items']);
511:         });
512:     }
513: 
514:     /** طلب المورد تعديل الأسعار/الكميات/الموعد مع ملاحظاته للإدارة. */
515:     public function supplierRequestChange(PurchaseOrder $po, SupplierUser $user, string $notes): PurchaseOrder
516:     {
517:         $this->assertOwnsOrder($po, $user);
518: 
519:         return DB::transaction(function () use ($po, $user, $notes): PurchaseOrder {
520:             $po = $this->lockOrder($po);
521:             $this->assertOwnsOrder($po, $user);
522:             if (! in_array($po->status, [PurchaseOrderStatus::SentToSupplier, PurchaseOrderStatus::SupplierAccepted], true)) {
523:                 throw new BusinessException("لا يمكن طلب تعديل على أمر شراء في حالة ({$po->status->value}).");
524:             }
525:             $po->update([
526:                 'status' => PurchaseOrderStatus::ChangeRequested,
527:                 'supplier_change_notes' => $notes,
528:             ]);
529: 
530:             return $po->fresh(['items']);
531:         });
532:     }
533: 
534:     /**
535:      * إشعار توريد (ASN) من المورد: كميات مشحونة فعليًا في هذه الدفعة +
536:      * فاتورة مبدئية مرفوعة. سقف الشحن التراكمي لكل بند = الكمية المطلوبة.
537:      *
538:      * @param  array{delivery_date: string, supplier_invoice_no?: string|null, notes?: string|null, items: list<array{purchase_order_item_id: int, shipped_qty: float|int|string}>}  $data
539:      */
540:     public function createSupplierDelivery(PurchaseOrder $po, SupplierUser $user, array $data, ?UploadedFile $invoiceFile = null, ?string $idempotencyKey = null): SupplierDelivery
541:     {
542:         $this->assertOwnsOrder($po->fresh(), $user);
543: 
544:         return PrivateAttachments::transaction(fn (PrivateAttachments $files) => app(OperationIdempotencyService::class)->run('supplier_delivery', $user, $idempotencyKey,
545:             ['purchase_order_id' => $po->id, ...$data, 'invoice_hash' => $invoiceFile ? hash_file('sha256', $invoiceFile->getRealPath()) : null],
546:             fn () => $this->executeSupplierDelivery($po, $user, $data, $invoiceFile, $files)));
547:     }
548: 
549:     private function executeSupplierDelivery(PurchaseOrder $po, SupplierUser $user, array $data, ?UploadedFile $invoiceFile, PrivateAttachments $files): SupplierDelivery
550:     {
551:         $this->assertOwnsOrder($po, $user);
552: 
553:         $delivery = DB::transaction(function () use ($po, $user, $data, $invoiceFile, $files): SupplierDelivery {
554:             $po = $this->lockOrder($po);
555:             $this->assertOwnsOrder($po, $user);
556:             if (! in_array($po->status, [
557:                 PurchaseOrderStatus::SentToSupplier,
558:                 PurchaseOrderStatus::SupplierAccepted,
559:                 PurchaseOrderStatus::PartiallyReceived,
560:             ], true)) {
561:                 throw new BusinessException("لا يمكن إرسال توريد لأمر شراء في حالة ({$po->status->value}).");
562:             }
563: 
564:             // تجميع البنود المكررة قبل فحص سقف الشحن التراكمي
565:             $lines = [];
566:             foreach ($data['items'] as $line) {
567:                 DiscreteQuantity::assert($line['shipped_qty']);
568:                 $itemId = (int) $line['purchase_order_item_id'];
569:                 $lines[$itemId] = ($lines[$itemId] ?? 0.0) + (float) $line['shipped_qty'];
570:             }
571: 
572:             $poItems = $po->items()->whereIn('id', array_keys($lines))->get()->keyBy('id');
573:             if ($poItems->count() !== count($lines)) {
574:                 throw new BusinessException('أحد بنود التوريد لا يتبع أمر الشراء هذا.');
575:             }
576:             foreach ($lines as $itemId => $shippedQty) {
577:                 $poItem = $poItems->get($itemId);
578:                 $pendingShipment = (float) SupplierDeliveryItem::query()
579:                     ->where('purchase_order_item_id', $itemId)
580:                     ->whereHas('delivery', fn ($q) => $q->where('status', SupplierDeliveryStatus::PendingReceipt->value))
581:                     ->selectRaw('COALESCE(SUM(shipped_qty - received_qty), 0) as total')->value('total');
582:                 if (round((float) $poItem->received_qty + $pendingShipment + $shippedQty, 4) > round((float) $poItem->ordered_qty, 4)) {
583:                     throw new BusinessException("إجمالي المشحون للصنف ({$poItem->variant?->sku}) يتجاوز الكمية المطلوبة في أمر الشراء.");
584:                 }
585:             }
586: 
587:             $delivery = SupplierDelivery::create([
588:                 'delivery_number' => $this->settings->generateNextNumber('delivery'),
589:                 'purchase_order_id' => $po->id,
590:                 'supplier_id' => (int) $user->supplier_id,
591:                 'status' => SupplierDeliveryStatus::PendingReceipt,
592:                 'delivery_date' => $data['delivery_date'],
593:                 'supplier_invoice_no' => $data['supplier_invoice_no'] ?? null,
594:                 'notes' => $data['notes'] ?? null,
595:             ]);
596:             foreach ($lines as $itemId => $shippedQty) {
597:                 $delivery->items()->create([
598:                     'purchase_order_item_id' => $itemId,
599:                     'product_variant_id' => $poItems->get($itemId)->product_variant_id,
600:                     'shipped_qty' => $shippedQty,
601:                 ]);
602:             }
603: 
604:             // الشحن دون قبول صريح = قبول ضمني بالالتزام
605:             if ($po->status === PurchaseOrderStatus::SentToSupplier) {
606:                 $po->update(['status' => PurchaseOrderStatus::SupplierAccepted]);
607:             }
608: 
609:             if ($invoiceFile !== null) {
610:                 $delivery->update(['invoice_file_path' => $files->store($invoiceFile, "supplier_deliveries/{$delivery->id}")]);
611:             }
612: 
613:             return $delivery;
614:         });
615: 
616:         return $delivery->fresh(['items']);
617:     }
