619:     /** حارس نطاق بوابة المورد: أمر شراء مورد آخر غير موجود أصلًا في عالم هذا المستخدم. */
620:     private function assertOwnsOrder(PurchaseOrder $po, SupplierUser $user): void
621:     {
622:         if ((int) $po->supplier_id !== (int) $user->supplier_id) {
623:             throw new BusinessException('أمر الشراء غير موجود.', [], 404);
624:         }
625:     }
