 24: /**
 25:  * خدمة المرتجعات (RMA) — دورة حياة طلب الإرجاع في أربع خطوات:
 26:  * create ← تقديم الطلب (تحقق من التسليم ونافذة الاسترجاع وسقف الكميات)،
 27:  * approve ← موافقة مبدئية (فرع مستلم وكميات معتمدة)،
 28:  * receive ← استلام وفحص فعلي، refund ← رد مالي للعميل.
 29:  *
 30:  * القاعدة الذهبية: الإنشاء والاعتماد لا يضيفان أي رصيد للمخزون. الإضافة
 31:  * الفعلية تتم حصريًا في receive عبر InventoryService::recordMovement:
 32:  * السليم يعود إلى on_hand بحركة sale_return، والتالف يُسجل في وعاء
 33:  * damaged بحركة damage (بعد عودته فيزيائيًا إلى on_hand بنفس الكمية،
 34:  * لأن وعاء التالف شريحة من الرصيد الفعلي لا رصيد مستقل).
 35:  */
 36: class ReturnService
 37: {
 38:     public function __construct(
 39:         protected SettingService $settings,
 40:         protected InventoryService $inventory,
 41:         protected OrderService $orders,
 42:     ) {}
 43: 
 44:     /**
 45:      * تقديم طلب إرجاع لطلب مُسلَّم داخل نافذة الاسترجاع.
 46:      * $customer عند الإنشاء من المتجر (يفرض ملكية الطلب)؛ null عند إنشاء
 47:      * الأدمن اليدوي لطلب أي عميل/زائر.
 48:      *
 49:      * @param  array{reason: string, refund_method?: string|null, items: list<array{order_item_id: int, requested_qty: float|int|string, item_reason?: string|null, attachments?: list<UploadedFile>}>}  $data
 50:      */
 51:     public function createReturnRequest(Order $order, array $data, ?Customer $customer = null): ReturnRequest
 52:     {
 53:         $return = PrivateAttachments::transaction(function (PrivateAttachments $files) use ($order, $data, $customer): ReturnRequest {
 54:             // قفل صف الطلب: طلبا إرجاع متزامنان لنفس البند لا يتجاوزا سقفه معًا
 55:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
 56: 
 57:             if ($customer !== null && (int) $order->customer_id !== (int) $customer->id) {
 58:                 throw new BusinessException('هذا الطلب لا يخص حسابك.', [], 403);
 59:             }
 60: 
 61:             if ($order->status !== OrderStatus::Delivered) {
 62:                 throw new BusinessException('لا يمكن إنشاء طلب إرجاع إلا لطلب تم تسليمه فعليًا.');
 63:             }
 64: 
 65:             $this->assertWithinReturnWindow($order);
 66: 
 67:             // تجميع البنود المكررة لنفس سطر الطلب قبل فحص السقف
 68:             $lines = [];
 69:             foreach ($data['items'] as $line) {
 70:                 DiscreteQuantity::assert($line['requested_qty']);
 71:                 $orderItemId = (int) $line['order_item_id'];
 72:                 $lines[$orderItemId] ??= ['qty' => 0.0, 'reason' => null, 'files' => []];
 73:                 $lines[$orderItemId]['qty'] += (float) $line['requested_qty'];
 74:                 $lines[$orderItemId]['reason'] = $line['item_reason'] ?? $lines[$orderItemId]['reason'];
 75:                 $lines[$orderItemId]['files'] = array_merge($lines[$orderItemId]['files'], $line['attachments'] ?? []);
 76:             }
 77: 
 78:             $orderItems = $order->items()->whereIn('id', array_keys($lines))->get()->keyBy('id');
 79:             if ($orderItems->count() !== count($lines)) {
 80:                 throw new BusinessException('أحد البنود المطلوب إرجاعها لا يتبع هذا الطلب.');
 81:             }
 82: 
 83:             foreach ($lines as $orderItemId => $line) {
 84:                 $orderItem = $orderItems->get($orderItemId);
 85:                 // ما سبق طلبه للإرجاع في طلبات قائمة (غير المرفوض/الملغي)
 86:                 // يحجز من سقف البند حتى لا يُرجع أكثر مما اشتراه العميل
 87:                 $previouslyRequested = (float) ReturnRequestItem::query()
 88:                     ->where('order_item_id', $orderItemId)
 89:                     ->join('return_requests', 'return_requests.id', '=', 'return_request_items.return_request_id')
 90:                     ->whereNotIn('return_requests.status', [ReturnStatus::Rejected->value, ReturnStatus::Cancelled->value])
 91:                     ->selectRaw("COALESCE(SUM(CASE WHEN return_requests.status IN ('received', 'refunded') THEN received_good_qty + received_damaged_qty WHEN return_requests.status = 'approved' THEN approved_qty ELSE requested_qty END), 0) as total")
 92:                     ->value('total');
 93:                 if (round($previouslyRequested + $line['qty'], 4) > round((float) $orderItem->qty, 4)) {
 94:                     throw new BusinessException("كمية الإرجاع للصنف ({$orderItem->sku_snapshot}) تتجاوز الكمية المشتراة بعد احتساب مرتجعات سابقة.");
 95:                 }
 96:             }
 97: 
 98:             $return = ReturnRequest::create([
 99:                 'return_number' => $this->settings->generateNextNumber('return'),
100:                 'order_id' => $order->id,
101:                 'customer_id' => $order->customer_id,
102:                 'status' => ReturnStatus::Pending,
103:                 'refund_method' => $data['refund_method'] ?? null,
104:                 'total_refund_amount' => 0,
105:                 'reason' => $data['reason'],
106:             ]);
107: 
108:             foreach ($lines as $orderItemId => $line) {
109:                 $orderItem = $orderItems->get($orderItemId);
110:                 $return->items()->create([
111:                     'order_item_id' => $orderItem->id,
112:                     'product_variant_id' => $orderItem->product_variant_id,
113:                     'requested_qty' => $line['qty'],
114:                     'unit_refund_price' => $this->netUnitRefundPrice($orderItem),
115:                     'item_reason' => $line['reason'],
116:                 ]);
117:             }
118: 
119:             $this->storeAttachments($return, $data['items'], $files);
120: 
121:             return $return;
122:         });
123: 
124:         return $return->fresh(['items']);
125:     }
