127:     /**
128:      * الموافقة المبدئية: تحديد الفرع المستلم والكميات المعتمدة لكل بند.
129:      * لا تلمس المخزون بأي شكل — الاستلام الفعلي لاحقًا هو ما يحرّكه.
130:      *
131:      * @param  array{branch_id: int, admin_notes?: string|null, items?: list<array{id: int, approved_qty: float|int|string}>}  $data
132:      */
133:     public function approve(ReturnRequest $return, User $admin, array $data): ReturnRequest
134:     {
135:         return DB::transaction(function () use ($return, $admin, $data): ReturnRequest {
136:             Order::query()->lockForUpdate()->findOrFail($return->order_id);
137:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
138:             if ($return->status !== ReturnStatus::Pending) {
139:                 throw new BusinessException('لا يمكن اعتماد طلب مرتجع إلا وهو قيد المراجعة.');
140:             }
141: 
142:             if (! Branch::query()->whereKey($data['branch_id'])->where('is_active', true)->exists()) {
143:                 throw new BusinessException('فرع الاستلام غير نشط.');
144:             }
145:             $return->load('items');
146:             $approved = collect($data['items'] ?? [])->keyBy(fn (array $line): int => (int) $line['id']);
147:             foreach ($approved->keys() as $itemId) {
148:                 if (! $return->items->contains('id', $itemId)) {
149:                     throw new BusinessException('أحد البنود المعتمدة لا يتبع طلب المرتجع هذا.');
150:                 }
151:             }
152: 
153:             $totalApproved = 0.0;
154:             foreach ($return->items as $item) {
155:                 // بند غير مذكور في الحمولة يُعتمد بكامل كميته المطلوبة
156:                 $qty = $approved->has($item->id)
157:                     ? (float) $approved->get($item->id)['approved_qty']
158:                     : (float) $item->requested_qty;
159:                 DiscreteQuantity::assert($qty, true);
160:                 if ($qty < 0 || round($qty, 4) > round((float) $item->requested_qty, 4)) {
161:                     throw new BusinessException("الكمية المعتمدة للصنف ({$item->orderItem?->sku_snapshot}) يجب أن تكون بين صفر والمطلوب.");
162:                 }
163:                 $item->update(['approved_qty' => $qty]);
164:                 $totalApproved += $qty;
165:             }
166:             if ($totalApproved <= 0) {
167:                 throw new BusinessException('لا توجد كميات معتمدة؛ ارفض الطلب بدلًا من اعتماده إن لم يُقبل أي بند.');
168:             }
169: 
170:             $return->update([
171:                 'branch_id' => (int) $data['branch_id'],
172:                 'status' => ReturnStatus::Approved,
173:                 'approved_by' => $admin->id,
174:                 'approved_at' => now(),
175:                 'admin_notes' => $data['admin_notes'] ?? $return->admin_notes,
176:             ]);
177: 
178:             return $return->fresh(['items']);
179:         });
180:     }
181: 
182:     /**
183:      * الاستلام والفحص المخزني — الخطوة الوحيدة التي تحرّك المخزون:
184:      * السليم sale_return إلى on_hand، والتالف damage إلى وعاء damaged،
185:      * داخل معاملة واحدة عبر InventoryService حصرًا.
186:      *
187:      * @param  array{items: list<array{id: int, received_good_qty: float|int|string, received_damaged_qty: float|int|string}>}  $data
188:      */
189:     public function receive(ReturnRequest $return, User $admin, array $data): ReturnRequest
190:     {
191:         return DB::transaction(function () use ($return, $admin, $data): ReturnRequest {
192:             Order::query()->lockForUpdate()->findOrFail($return->order_id);
193:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
194:             if ($return->status !== ReturnStatus::Approved) {
195:                 throw new BusinessException('لا يمكن استلام مرتجع إلا بعد الموافقة المبدئية عليه.');
196:             }
197:             if ($return->branch_id === null) {
198:                 throw new BusinessException('لم يُحدد فرع الاستلام عند اعتماد هذا المرتجع.');
199:             }
200: 
201:             $return->load('items');
202:             $lines = collect($data['items'])->keyBy(fn (array $line): int => (int) $line['id']);
203:             foreach ($lines->keys() as $itemId) {
204:                 if (! $return->items->contains('id', $itemId)) {
205:                     throw new BusinessException('أحد البنود المستلمة لا يتبع طلب المرتجع هذا.');
206:                 }
207:             }
208:             foreach ($return->items as $item) {
209:                 if (! $lines->has($item->id)) {
210:                     throw new BusinessException('بيانات الاستلام يجب أن تغطي كل بنود المرتجع (بند بلا استلام فعلي يُرسل بصفر).');
211:                 }
212:             }
213: 
214:             $refundTotal = 0.0;
215:             foreach ($return->items as $item) {
216:                 $line = $lines->get($item->id);
217:                 DiscreteQuantity::assert($line['received_good_qty'], true);
218:                 DiscreteQuantity::assert($line['received_damaged_qty'], true);
219:                 $good = (float) $line['received_good_qty'];
220:                 $damaged = (float) $line['received_damaged_qty'];
221:                 if (round($good + $damaged, 4) > round((float) $item->approved_qty, 4)) {
222:                     throw new BusinessException("المستلم للصنف ({$item->orderItem?->sku_snapshot}) يتجاوز الكمية المعتمدة.");
223:                 }
224: 
225:                 $base = [
226:                     'product_variant_id' => $item->product_variant_id,
227:                     'branch_id' => (int) $return->branch_id,
228:                     'location_id' => null,
229:                     'reference_type' => ReturnRequest::class,
230:                     'reference_id' => $return->id,
231:                     'created_by' => $admin->id,
232:                 ];
233:                 if ($good > 0) {
234:                     $this->inventory->recordMovement([...$base,
235:                         'type' => StockMovementType::SaleReturn,
236:                         'affected_bucket' => StockBucket::OnHand,
237:                         'quantity' => $good,
238:                         'notes' => "مرتجع سليم — طلب {$return->return_number}",
239:                     ]);
240:                 }
241:                 if ($damaged > 0) {
242:                     // القطعة التالفة عادت فيزيائيًا للمخزن فتدخل on_hand أولًا،
243:                     // ثم تُحجز في وعاء التالف — المتاح للبيع لا يزيد بها
244:                     $this->inventory->recordMovement([...$base,
245:                         'type' => StockMovementType::SaleReturn,
246:                         'affected_bucket' => StockBucket::OnHand,
247:                         'quantity' => $damaged,
248:                         'notes' => "مرتجع تالف (عودة فيزيائية) — طلب {$return->return_number}",
249:                     ]);
250:                     $this->inventory->recordMovement([...$base,
251:                         'type' => StockMovementType::Damage,
252:                         'affected_bucket' => StockBucket::Damaged,
253:                         'quantity' => $damaged,
254:                         'notes' => "مرتجع تالف بعد الفحص — طلب {$return->return_number}",
255:                     ]);
256:                 }
257: 
258:                 $receivedTotal = $good + $damaged;
259:                 if ($receivedTotal > 0) {
260:                     $product = $item->variant?->product;
261:                     if ($product !== null) {
262:                         $product->update(['sales_count' => max(0, (int) $product->sales_count - (int) round($receivedTotal))]);
263:                     }
264:                 }
265: 
266:                 $previous = ReturnRequestItem::query()->where('order_item_id', $item->order_item_id)
267:                     ->where('id', '!=', $item->id)->whereHas('returnRequest', fn ($q) => $q->whereIn('status', [ReturnStatus::Received, ReturnStatus::Refunded]))
268:                     ->selectRaw('COALESCE(SUM(received_good_qty + received_damaged_qty), 0) as qty, COALESCE(SUM(refund_amount), 0) as refunded')->first();
269:                 $orderItem = $item->orderItem;
270:                 $netCents = (int) round(max(0, (float) $orderItem->unit_price * (float) $orderItem->qty - (float) $orderItem->discount_amount) * 100);
271:                 $cumulativeQty = (float) $previous->qty + $receivedTotal;
272:                 $targetCents = $cumulativeQty >= (float) $orderItem->qty
273:                     ? $netCents
274:                     : min($netCents, (int) round($cumulativeQty * (float) $item->unit_refund_price * 100));
275:                 $refundAmount = max(0, $targetCents - (int) round((float) $previous->refunded * 100)) / 100;
276:                 $item->update([
277:                     'refund_amount' => $refundAmount,
278:                     'received_good_qty' => $good,
279:                     'received_damaged_qty' => $damaged,
280:                 ]);
281:                 $refundTotal += $refundAmount;
282:             }
283: 
284:             $return->update([
285:                 'total_refund_amount' => round($refundTotal, 2),
286:                 'status' => ReturnStatus::Received,
287:                 'received_by' => $admin->id,
288:                 'received_at' => now(),
289:             ]);
290: 
291:             return $return->fresh(['items']);
292:         });
293:     }
