295:     /**
296:      * رد المبلغ للعميل بعد الاستلام: محفظة (تُضاف لرصيد العميل) أو تسجيل
297:      * مرجع تحويل/بوابة. اكتمال إرجاع كل بنود الطلب ينقل الطلب نفسه إلى
298:      * Returned عبر بوابة الحالة بلا آثار مخزون/استرداد مكررة.
299:      *
300:      * @param  array{refund_method?: string|null, refund_reference?: string|null}  $data
301:      */
302:     public function refund(ReturnRequest $return, User $admin, array $data): ReturnRequest
303:     {
304:         return DB::transaction(function () use ($return, $admin, $data): ReturnRequest {
305:             $order = Order::query()->lockForUpdate()->findOrFail($return->order_id);
306:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
307:             if ($return->status !== ReturnStatus::Received) {
308:                 throw new BusinessException('لا يمكن رد مبلغ مرتجع إلا بعد استلامه وفحصه.');
309:             }
310: 
311:             $method = $data['refund_method'] ?? $return->refund_method?->value;
312:             if ($method === null) {
313:                 throw new BusinessException('حدد طريقة رد المبلغ قبل إتمام الاسترداد.');
314:             }
315:             $reference = $data['refund_reference'] ?? $return->refund_reference;
316:             if (in_array($method, [RefundMethod::OriginalPayment->value, RefundMethod::BankTransfer->value], true)
317:                 && trim((string) $reference) === '') {
318:                 throw new BusinessException('مرجع التحويل أو بوابة الدفع مطلوب لإتمام الاسترداد.');
319:             }
320: 
321:             if ($method === RefundMethod::Wallet->value) {
322:                 if ($return->customer_id === null) {
323:                     throw new BusinessException('الاسترداد إلى المحفظة يتطلب حساب عميل مسجل؛ اختر طريقة أخرى لطلبات الزوار.');
324:                 }
325:                 app(WalletService::class)->record($return->customer_id, (float) $return->total_refund_amount,
326:                     'return_refund', 'return_request', $return->id, $admin->id);
327:             }
328: 
329:             $return->update([
330:                 'refund_method' => $method,
331:                 'refund_reference' => $reference,
332:                 'status' => ReturnStatus::Refunded,
333:                 'refunded_by' => $admin->id,
334:                 'refunded_at' => now(),
335:             ]);
336: 
337:             if ($this->isOrderFullyReturned($order)) {
338:                 $refundedCents = (int) round((float) $order->returnRequests()->where('status', ReturnStatus::Refunded)->sum('total_refund_amount') * 100);
339:                 if ($order->payment_status === 'paid' && $refundedCents >= (int) round((float) $order->grand_total * 100)) {
340:                     $order->update(['payment_status' => 'refunded', 'requires_refund' => false]);
341:                 }
342:                 $this->orders->changeStatus(
343:                     $order,
344:                     OrderStatus::Returned,
345:                     $admin,
346:                     "إرجاع كامل لبنود الطلب عبر طلب المرتجع {$return->return_number}",
347:                     null,
348:                     false,
349:                 );
350:             }
351: 
352:             return $return->fresh(['items']);
353:         });
354:     }
