356:     public function delete(ReturnRequest $return): void
357:     {
358:         DB::transaction(function () use ($return): void {
359:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
360:             if ($return->status !== ReturnStatus::Pending) {
361:                 throw new BusinessException('يمكن حذف المرتجعات قيد المراجعة فقط؛ استخدم الإلغاء للحالات الأخرى.');
362:             }
363:             $paths = $return->items()->get()->flatMap(fn ($item) => $item->attachments ?? [])->all();
364:             $return->delete();
365:             DB::afterCommit(function () use ($paths): void {
366:                 Storage::disk('local')->delete($paths);
367:                 Storage::disk('public')->delete($paths);
368:             });
369:         });
370:     }
