372:     /** رفض طلب قيد المراجعة — بلا أي أثر (لم يتحرك مخزون ولا مال). */
373:     public function reject(ReturnRequest $return, User $admin, ?string $notes = null): ReturnRequest
374:     {
375:         return DB::transaction(function () use ($return, $notes): ReturnRequest {
376:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
377:             if ($return->status !== ReturnStatus::Pending) {
378:                 throw new BusinessException('لا يمكن رفض طلب مرتجع إلا وهو قيد المراجعة.');
379:             }
380:             $return->update([
381:                 'status' => ReturnStatus::Rejected,
382:                 'admin_notes' => $notes ?? $return->admin_notes,
383:             ]);
384: 
385:             return $return->fresh(['items']);
386:         });
387:     }
