389:     /** إلغاء طلب لم يُستلم بعد (قيد المراجعة/معتمد) — بلا أي أثر مخزني. */
390:     public function cancel(ReturnRequest $return, ?string $notes = null): ReturnRequest
391:     {
392:         return DB::transaction(function () use ($return, $notes): ReturnRequest {
393:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
394:             if (! in_array($return->status, [ReturnStatus::Pending, ReturnStatus::Approved], true)) {
395:                 throw new BusinessException('لا يمكن إلغاء مرتجع بعد استلامه.');
396:             }
397:             $return->update([
398:                 'status' => ReturnStatus::Cancelled,
399:                 'admin_notes' => $notes ?? $return->admin_notes,
400:             ]);
401: 
402:             return $return->fresh(['items']);
403:         });
404:     }
