406:     /**
407:      * تعديلات إدارية بلا آثار جانبية: ملاحظات وطريقة رد (قبل اكتمال الرد)،
408:      * وتوجيه حالتي rejected/cancelled لمساريهما في الخدمة.
409:      *
410:      * @param  array{admin_notes?: string|null, refund_method?: string|null, status?: string|null}  $data
411:      */
412:     public function updateDetails(ReturnRequest $return, User $admin, array $data): ReturnRequest
413:     {
414:         if (($data['status'] ?? null) === ReturnStatus::Rejected->value) {
415:             return $this->reject($return, $admin, $data['admin_notes'] ?? null);
416:         }
417:         if (($data['status'] ?? null) === ReturnStatus::Cancelled->value) {
418:             return $this->cancel($return, $data['admin_notes'] ?? null);
419:         }
420: 
421:         return DB::transaction(function () use ($return, $data): ReturnRequest {
422:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
423:             if (! in_array($return->status, [ReturnStatus::Pending, ReturnStatus::Approved, ReturnStatus::Received], true)
424:                 && array_key_exists('refund_method', $data)) {
425:                 throw new BusinessException('لا يمكن تغيير طريقة الرد بعد اكتمال الاسترداد.');
426:             }
427: 
428:             $updates = [];
429:             if (array_key_exists('admin_notes', $data)) {
430:                 $updates['admin_notes'] = $data['admin_notes'];
431:             }
432:             if (array_key_exists('refund_method', $data)) {
433:                 $updates['refund_method'] = $data['refund_method'];
434:             }
435:             if ($updates !== []) {
436:                 $return->update($updates);
437:             }
438: 
439:             return $return->fresh(['items']);
440:         });
441:     }
