443:     /** نافذة الاسترجاع من الإعدادات (أيام من لحظة انتقال الطلب إلى delivered). */
444:     private function assertWithinReturnWindow(Order $order): void
445:     {
446:         $windowDays = (int) $this->settings->get('return_window_days', 14);
447:         if ($windowDays <= 0) {
448:             return;
449:         }
450: 
451:         $deliveredAt = $order->statusHistories()
452:             ->where('to_status', OrderStatus::Delivered->value)
453:             ->latest('id')
454:             ->value('created_at');
455: 
456:         if ($deliveredAt === null) {
457:             throw new BusinessException('لا يوجد سجل تسليم موثوق لحساب فترة الاسترجاع.');
458:         }
459: 
460:         if ($deliveredAt !== null && $deliveredAt->copy()->addDays($windowDays)->isPast()) {
461:             throw new BusinessException("انتهت فترة الاسترجاع المسموحة ({$windowDays} يومًا من التسليم) لهذا الطلب.");
462:         }
463:     }
