465:     /** سعر وحدة الرد الصافي: ما دفعه العميل فعليًا للبند ÷ كميته (بعد خصومات الأسعار وحصة الكوبون). */
466:     private function netUnitRefundPrice(OrderItem $orderItem): float
467:     {
468:         $qty = (float) $orderItem->qty;
469:         if ($qty <= 0) {
470:             return (float) $orderItem->unit_price;
471:         }
472:         $net = (float) $orderItem->unit_price * $qty - (float) $orderItem->discount_amount;
473: 
474:         return round(max(0.0, $net) / $qty, 4);
475:     }
