477:     /**
478:      * حفظ صور العيوب على القرص الخاص داخل معاملة إنشاء المرتجع،
479:      * وتسجيل مساراتها في attachments البند.
480:      *
481:      * @param  list<array{order_item_id: int, attachments?: list<UploadedFile>}>  $rawItems
482:      */
483:     private function storeAttachments(ReturnRequest $return, array $rawItems, PrivateAttachments $files): void
484:     {
485:         $filesByOrderItem = [];
486:         foreach ($rawItems as $line) {
487:             foreach ($line['attachments'] ?? [] as $file) {
488:                 if ($file instanceof UploadedFile) {
489:                     $filesByOrderItem[(int) $line['order_item_id']][] = $file;
490:                 }
491:             }
492:         }
493:         if ($filesByOrderItem === []) {
494:             return;
495:         }
496: 
497:         $return->load('items');
498:         foreach ($return->items as $item) {
499:             $itemFiles = $filesByOrderItem[(int) $item->order_item_id] ?? [];
500:             if ($itemFiles === []) {
501:                 continue;
502:             }
503:             $paths = [];
504:             foreach ($itemFiles as $file) {
505:                 $paths[] = $files->store($file, "return_requests/{$return->id}");
506:             }
507:             $item->update(['attachments' => array_merge($item->attachments ?? [], $paths)]);
508:         }
509:     }
