511:     /** هل اكتمل استلام ورد قيمة كل بنود الطلب عبر المرتجعات؟ */
512:     private function isOrderFullyReturned(Order $order): bool
513:     {
514:         $items = $order->items()->get();
515:         if ($items->isEmpty()) {
516:             return false;
517:         }
518: 
519:         foreach ($items as $orderItem) {
520:             $received = (float) ReturnRequestItem::query()
521:                 ->where('order_item_id', $orderItem->id)
522:                 ->whereHas('returnRequest', fn ($q) => $q->whereIn('status', [
523:                     ReturnStatus::Refunded->value,
524:                 ]))
525:                 ->selectRaw('COALESCE(SUM(received_good_qty + received_damaged_qty), 0) as total')
526:                 ->value('total');
527:             if (round($received, 4) < round((float) $orderItem->qty, 4)) {
528:                 return false;
529:             }
530:         }
531: 
532:         return true;
533:     }
