137:     /** إلغاء فاتورة: المسودة بلا أثر؛ والمعتمدة غير المسددة تعكس رصيدها. */
138:     public function cancelInvoice(SupplierInvoice $invoice): SupplierInvoice
139:     {
140:         return DB::transaction(function () use ($invoice): SupplierInvoice {
141:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($invoice->supplier_id);
142:             $invoice = SupplierInvoice::query()->where('supplier_id', $supplier->id)->lockForUpdate()->findOrFail($invoice->id);
143:             if ($invoice->status === SupplierInvoiceStatus::Draft) {
144:                 $invoice->update(['status' => SupplierInvoiceStatus::Cancelled]);
145: 
146:                 return $invoice->fresh();
147:             }
148:             if ($invoice->status === SupplierInvoiceStatus::Posted && (float) $invoice->paid_amount <= 0) {
149:                 $supplier->decrement('current_balance', (float) $invoice->total_amount);
150:                 $invoice->update(['status' => SupplierInvoiceStatus::Cancelled]);
151: 
152:                 return $invoice->fresh();
153:             }
154: 
155:             throw new BusinessException('لا يمكن إلغاء فاتورة بدأ سدادها؛ عالِج دفعاتها أولًا.');
156:         });
157:     }
158: 
159:     public function deleteInvoice(SupplierInvoice $invoice): void
160:     {
161:         DB::transaction(function () use ($invoice): void {
162:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($invoice->supplier_id);
163:             $invoice = SupplierInvoice::query()->where('supplier_id', $supplier->id)->lockForUpdate()->findOrFail($invoice->id);
164:             if ($invoice->status !== SupplierInvoiceStatus::Draft) {
165:                 throw new BusinessException('يمكن حذف الفواتير المسودة فقط؛ يحتفظ بالسجلات الأخرى للتدقيق.');
166:             }
167:             $path = $invoice->attachment_path;
168:             $invoice->delete();
169:             if ($path) {
170:                 DB::afterCommit(fn () => Storage::disk('local')->delete($path));
171:             }
172:         });
173:     }
174: 
175:     /**
176:      * تسجيل دفعة لمورد: تخفض رصيده، وتُسند لفاتورة معتمدة عند ربطها
177:      * (بسقف المتبقي منها) فتتحدث paid_amount وحالتها.
178:      *
179:      * @param  array{supplier_id: int, supplier_invoice_id?: int|null, amount: float|int|string, payment_method: string, reference_no?: string|null, payment_date: string, notes?: string|null}  $data
180:      */
181:     public function createPayment(array $data, User $creator, ?string $idempotencyKey = null): SupplierPayment
182:     {
183:         return app(OperationIdempotencyService::class)->run('supplier_payment', $creator, $idempotencyKey, $data,
184:             fn () => $this->executePayment($data, $creator, hash('sha256', $creator->id.':'.$idempotencyKey)));
185:     }
186: 
187:     private function executePayment(array $data, User $creator, string $idempotencyKey): SupplierPayment
188:     {
189:         return DB::transaction(function () use ($data, $creator, $idempotencyKey): SupplierPayment {
190:             $supplier = Supplier::query()->lockForUpdate()->findOrFail((int) $data['supplier_id']);
191:             $amount = round((float) $data['amount'], 2);
192:             if ($amount <= 0 || $amount > 9999999999.99) {
193:                 throw new BusinessException('مبلغ الدفعة يجب أن يكون أكبر من صفر.');
194:             }
195: 
196:             $invoice = null;
197:             if (! empty($data['supplier_invoice_id'])) {
198:                 $invoice = SupplierInvoice::query()->lockForUpdate()
199:                     ->where('supplier_id', $supplier->id)
200:                     ->find((int) $data['supplier_invoice_id']);
201:                 if ($invoice === null) {
202:                     throw new BusinessException('الفاتورة المرتبطة غير موجودة لهذا المورد.');
203:                 }
204:                 if (! in_array($invoice->status, [SupplierInvoiceStatus::Posted, SupplierInvoiceStatus::PartiallyPaid], true)) {
205:                     throw new BusinessException('لا يمكن سداد فاتورة إلا وهي معتمدة أو مسددة جزئيًا.');
206:                 }
207:                 $remaining = round((float) $invoice->total_amount - (float) $invoice->paid_amount, 2);
208:                 if ($amount > $remaining) {
209:                     throw new BusinessException("مبلغ الدفعة ({$amount}) أكبر من المتبقي على الفاتورة ({$remaining}).");
210:                 }
211:             }
212: 
213:             $reference = $this->paymentReference($supplier->id, $data['payment_method'], $data['reference_no'] ?? null);
214:             $payment = SupplierPayment::create([
215:                 'payment_number' => $this->settings->generateNextNumber('supplier_payment'),
216:                 'idempotency_key' => $idempotencyKey,
217:                 'supplier_id' => $supplier->id,
218:                 'supplier_invoice_id' => $invoice?->id,
219:                 'amount' => $amount,
220:                 'payment_method' => $data['payment_method'],
221:                 'reference_no' => $reference,
222:                 'payment_date' => $data['payment_date'],
223:                 'notes' => $data['notes'] ?? null,
224:                 'created_by' => $creator->id,
225:             ]);
226: 
227:             $supplier->decrement('current_balance', $amount);
228:             if ($invoice !== null) {
229:                 $invoice->increment('paid_amount', $amount);
230:                 $this->syncInvoicePaidStatus($invoice->fresh());
231:             }
232: 
233:             return $payment->fresh();
234:         });
235:     }
236: 
237:     public function updatePayment(SupplierPayment $payment, array $data): SupplierPayment
238:     {
239:         return DB::transaction(function () use ($payment, $data): SupplierPayment {
240:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($payment->supplier_id);
241:             $payment = SupplierPayment::query()->where('supplier_id', $supplier->id)->lockForUpdate()->findOrFail($payment->id);
242:             $method = $data['payment_method'] ?? $payment->payment_method->value;
243:             $reference = array_key_exists('reference_no', $data) ? $data['reference_no'] : $payment->reference_no;
244:             $data['reference_no'] = $this->paymentReference($supplier->id, $method, $reference, $payment->id);
245:             $payment->update(array_intersect_key($data, array_flip(['payment_method', 'reference_no', 'payment_date', 'notes'])));
246: 
247:             return $payment->fresh();
248:         });
249:     }
250: 
251:     private function paymentReference(int $supplierId, string $method, ?string $reference, ?int $exceptId = null): ?string
252:     {
253:         $reference = $reference !== null ? trim($reference) : null;
254:         if ($method !== 'cash' && ($reference === null || $reference === '')) {
255:             throw new BusinessException('مرجع الدفع مطلوب للدفعات غير النقدية.');
256:         }
257:         if ($method !== 'cash' && SupplierPayment::query()->where('supplier_id', $supplierId)
258:             ->where('payment_method', '!=', 'cash')->when($exceptId, fn ($q) => $q->where('id', '!=', $exceptId))
259:             ->whereRaw('lower(btrim(reference_no)) = ?', [mb_strtolower($reference)])->exists()) {
260:             throw new BusinessException('مرجع الدفع مسجل سابقًا لهذا المورد.', [], 409);
261:         }
262: 
263:         return $reference;
264:     }
265: 
266:     /** حذف دفعة يعكس أثرها كاملًا: رصيد المورد ومدفوعات فاتورتها. */
267:     public function deletePayment(SupplierPayment $payment): void
268:     {
269:         DB::transaction(function () use ($payment): void {
270:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($payment->supplier_id);
271:             $payment = SupplierPayment::query()->where('supplier_id', $supplier->id)->lockForUpdate()->findOrFail($payment->id);
272:             $supplier->increment('current_balance', (float) $payment->amount);
273: 
274:             if ($payment->supplier_invoice_id !== null) {
275:                 $invoice = SupplierInvoice::query()->lockForUpdate()->find($payment->supplier_invoice_id);
276:                 if ($invoice !== null && $invoice->status !== SupplierInvoiceStatus::Cancelled) {
277:                     $invoice->decrement('paid_amount', (float) $payment->amount);
278:                     $this->syncInvoicePaidStatus($invoice->fresh());
279:                 }
280:             }
281:             $payment->delete();
282:         });
283:     }
284: 
285:     /** حالة الفاتورة من مدفوعاتها: صفر ← posted، جزئي ← partially_paid، كامل ← paid. */
286:     private function syncInvoicePaidStatus(SupplierInvoice $invoice): void
287:     {
288:         if ($invoice->status === SupplierInvoiceStatus::Draft
289:             || $invoice->status === SupplierInvoiceStatus::Cancelled) {
290:             return;
291:         }
292:         $paid = round((float) $invoice->paid_amount, 2);
293:         $total = round((float) $invoice->total_amount, 2);
294:         $invoice->update(['status' => match (true) {
295:             $paid >= $total => SupplierInvoiceStatus::Paid,
296:             $paid > 0 => SupplierInvoiceStatus::PartiallyPaid,
297:             default => SupplierInvoiceStatus::Posted,
298:         }]);
299:     }
300: 
301:     private function assertInvoiceNumberAvailable(int $supplierId, string $number, ?int $exceptId = null): void
302:     {
303:         if (SupplierInvoice::query()->where('supplier_id', $supplierId)->where('status', '!=', SupplierInvoiceStatus::Cancelled)
304:             ->when($exceptId, fn ($q) => $q->where('id', '!=', $exceptId))
305:             ->whereRaw('lower(btrim(supplier_invoice_no)) = ?', [mb_strtolower(trim($number))])->exists()) {
306:             throw new BusinessException('رقم فاتورة المورد مسجل سابقًا.', [], 409);
307:         }
308:     }
309: 
310:     private function assertOrderBelongsToSupplier(mixed $poId, Supplier $supplier): ?int
311:     {
312:         if ($poId === null || $poId === '') {
313:             return null;
314:         }
315:         $po = PurchaseOrder::query()->find((int) $poId);
316:         if ($po === null || (int) $po->supplier_id !== (int) $supplier->id) {
317:             throw new BusinessException('أمر الشراء المرتبط لا يخص هذا المورد.');
318:         }
319: 
320:         return $po->id;
321:     }
322: 
323:     /**
324:      * كشف حساب المورد (Ledger) لفترة: رصيد افتتاحي محسوب من كل الحركات
325:      * قبل الفترة، ثم حركات الفترة بترتيب زمني مع رصيد تراكمي متحرك:
326:      * الفواتير المعتمدة Credit (+) والدفعات Debit (−).
327:      *
328:      * @return array<string, mixed>
329:      */
330:     public function statement(Supplier $supplier, ?string $fromDate = null, ?string $toDate = null): array
331:     {
332:         $to = $toDate !== null ? Carbon::parse($toDate)->toDateString() : now()->toDateString();
333:         $from = $fromDate !== null ? Carbon::parse($fromDate)->toDateString() : Carbon::parse($to)->subDays(365)->toDateString();
334:         if (Carbon::parse($from)->gt(Carbon::parse($to)) || Carbon::parse($from)->diffInDays(Carbon::parse($to)) > 366) {
335:             throw new BusinessException('فترة كشف الحساب يجب ألا تتجاوز 366 يومًا وبترتيب زمني صحيح.');
336:         }
337:         $countedStatuses = [
338:             SupplierInvoiceStatus::Posted->value,
339:             SupplierInvoiceStatus::PartiallyPaid->value,
340:             SupplierInvoiceStatus::Paid->value,
341:         ];
342: 
343:         $creditBefore = (float) SupplierInvoice::query()
344:             ->where('supplier_id', $supplier->id)
345:             ->whereIn('status', $countedStatuses)
346:             ->where('issue_date', '<', $from)
347:             ->sum('total_amount');
348:         $debitBefore = (float) SupplierPayment::query()
349:             ->where('supplier_id', $supplier->id)
350:             ->where('payment_date', '<', $from)
351:             ->sum('amount');
352:         $running = round((float) $supplier->opening_balance + $creditBefore - $debitBefore, 2);
353:         $periodOpening = $running;
354: 
355:         $invoices = SupplierInvoice::query()
356:             ->with('purchaseOrder:id,po_number')
357:             ->where('supplier_id', $supplier->id)
358:             ->whereIn('status', $countedStatuses)
359:             ->whereBetween('issue_date', [$from, $to])
360:             ->get()
361:             ->map(fn (SupplierInvoice $inv): array => [
362:                 'date' => $inv->issue_date->toDateString(),
363:                 'type' => 'invoice',
364:                 'reference' => $inv->invoice_number,
365:                 'description' => 'فاتورة مورد '.$inv->supplier_invoice_no.($inv->purchaseOrder !== null ? ' — أمر شراء '.$inv->purchaseOrder->po_number : ''),
366:                 'credit' => round((float) $inv->total_amount, 2),
367:                 'debit' => 0.0,
368:                 'sort' => [$inv->issue_date->toDateString(), 0, $inv->id],
369:             ]);
370:         $payments = SupplierPayment::query()
371:             ->with('invoice:id,invoice_number')
372:             ->where('supplier_id', $supplier->id)
373:             ->whereBetween('payment_date', [$from, $to])
374:             ->get()
375:             ->map(fn (SupplierPayment $pay): array => [
376:                 'date' => $pay->payment_date->toDateString(),
377:                 'type' => 'payment',
378:                 'reference' => $pay->payment_number,
379:                 'description' => 'دفعة للمورد'.($pay->invoice !== null ? ' — سداد فاتورة '.$pay->invoice->invoice_number : ''),
380:                 'credit' => 0.0,
381:                 'debit' => round((float) $pay->amount, 2),
382:                 'sort' => [$pay->payment_date->toDateString(), 1, $pay->id],
383:             ]);
384: 
385:         $entries = [];
386:         $totalCredit = 0.0;
387:         $totalDebit = 0.0;
388:         foreach ($invoices->concat($payments)->sortBy(fn (array $e): array => $e['sort'])->values() as $entry) {
389:             $running = round($running + $entry['credit'] - $entry['debit'], 2);
390:             $totalCredit += $entry['credit'];
391:             $totalDebit += $entry['debit'];
392:             unset($entry['sort']);
393:             $entry['running_balance'] = $running;
394:             $entries[] = $entry;
395:         }
396: 
397:         return [
398:             'supplier' => [
399:                 'id' => $supplier->id,
400:                 'code' => $supplier->code,
401:                 'name' => $supplier->name,
402:                 'current_balance' => $supplier->current_balance,
403:             ],
404:             'from_date' => $from,
405:             'to_date' => $to,
406:             'opening_balance' => $periodOpening,
407:             'entries' => $entries,
408:             'total_credit' => round($totalCredit, 2),
409:             'total_debit' => round($totalDebit, 2),
410:             'closing_balance' => $running,
411:         ];
412:     }
