 9: 
10: /**
11:  * إدارة الموردين: قاعدة الرصيد الوحيدة هنا أن current_balance يبدأ من
12:  * opening_balance لحظة الإنشاء؛ بعدها لا يتحرك إلا عبر SupplierFinanceService
13:  * (اعتماد فواتير ودفعات) — تعديل بيانات المورد لا يمس رصيده الجاري.
14:  */
15: class SupplierService
16: {
17:     /**
18:      * @param  array<string, mixed>  $data
19:      */
20:     public function create(array $data): Supplier
21:     {
22:         return DB::transaction(function () use ($data): Supplier {
23:             $data['current_balance'] = $data['opening_balance'] ?? 0;
24: 
25:             return Supplier::create($data);
26:         });
27:     }
28: 
29:     /**
30:      * @param  array<string, mixed>  $data
31:      */
32:     public function update(Supplier $supplier, array $data): Supplier
33:     {
34:         // الرصيد الجاري نتيجة دفترية — لا يُعدَّل يدويًا من شاشة المورد
35:         return DB::transaction(function () use ($supplier, $data): Supplier {
36:             $supplier = Supplier::query()->lockForUpdate()->findOrFail($supplier->id);
37:             unset($data['current_balance']);
38:             if (array_key_exists('opening_balance', $data)) {
39:                 $data['current_balance'] = round((float) $supplier->current_balance
40:                     + (float) $data['opening_balance'] - (float) $supplier->opening_balance, 2);
41:             }
42:             $supplier->update($data);
43: 
44:             return $supplier->fresh();
45:         });
46:     }
