 83:     private function deliveredOrder(Customer $customer, ProductVariant $variant, int $qty): Order
 84:     {
 85:         $city = City::factory()->create(['shipping_cost' => 0]);
 86:         $token = $customer->createToken('store-token')->plainTextToken;
