112:     /** إنشاء مرتجع من حساب العميل — يرجع بيانات الرد. */
113:     private function storeCreateReturn(Customer $customer, Order $order, int $orderItemId, float $qty, array $extra = []): TestResponse
114:     {
115:         Auth::forgetGuards();
116: 
117:         return $this->withToken($this->customerToken($customer))->postJson('/api/v1/store/account/returns', array_merge([
118:             'order_id' => $order->id,
119:             'reason' => 'مقاس غير مناسب',
120:             'items' => [['order_item_id' => $orderItemId, 'requested_qty' => $qty]],
121:         ], $extra));
122:     }
123: 
124:     private function adminPost(string $url, array $data = []): TestResponse
125:     {
126:         Auth::forgetGuards();
127: 
128:         return $this->withToken($this->staffToken)->postJson($url, $data);
129:     }
