131:     /** رصيد مستوى الفرع العام (بلا موقع) الذي يستقبل المرتجعات. */
132:     private function branchLevel(ProductVariant $variant): ?StockLevel
133:     {
134:         return StockLevel::query()
135:             ->where('branch_id', $this->branch->id)
136:             ->whereNull('location_id')
137:             ->where('product_variant_id', $variant->id)
138:             ->first();
139:     }
