162:     public function test_create_rejected_for_non_delivered_or_foreign_or_over_quantity_or_expired(): void
163:     {
164:         $variant = $this->purchasableVariant(100);
165:         $this->giveStock($variant, 30);
166:         $customer = Customer::factory()->create();
167:         $other = Customer::factory()->create();
168: 
169:         // طلب لم يُسلَّم بعد (pending)
170:         $city = City::factory()->create(['shipping_cost' => 0]);
171:         $token = $this->customerToken($customer);
172:         Auth::forgetGuards();
173:         $this->withToken($token)->postJson('/api/v1/store/cart/items', [
174:             'product_variant_id' => $variant->id, 'qty' => 1,
175:         ])->assertOk();
176:         Auth::forgetGuards();
177:         $pendingId = $this->withToken($token)->postJson('/api/v1/store/checkout', [
178:             'city_id' => $city->id, 'shipping_address_line' => 'عنوان', 'payment_method' => 'cod',
179:         ])->assertCreated()->json('data.id');
180:         $pendingItem = Order::findOrFail($pendingId)->items->first();
181:         $this->storeCreateReturn($customer, Order::findOrFail($pendingId), $pendingItem->id, 1)
182:             ->assertUnprocessable();
183: 
184:         $order = $this->deliveredOrder($customer, $variant, 3);
185:         $orderItem = $order->items->first();
186: 
187:         // طلب يخص عميلًا آخر = 404
188:         $this->storeCreateReturn($other, $order, $orderItem->id, 1)->assertNotFound();
189: 
190:         // تجاوز الكمية المشتراة
191:         $this->storeCreateReturn($customer, $order, $orderItem->id, 4)->assertUnprocessable();
192: 
193:         // طلبان متتاليان: 2 ثم 2 يتجاوز 3، أما 2 ثم 1 فيمر
194:         $this->storeCreateReturn($customer, $order, $orderItem->id, 2)->assertCreated();
195:         $this->storeCreateReturn($customer, $order, $orderItem->id, 2)->assertUnprocessable();
196:         $this->storeCreateReturn($customer, $order, $orderItem->id, 1)->assertCreated();
197: 
198:         // انتهاء نافذة الاسترجاع (14 يومًا): تسليم قديم يُرفض
199:         $oldOrder = $this->deliveredOrder($customer, $variant, 1);
200:         OrderStatusHistory::query()
201:             ->where('order_id', $oldOrder->id)->where('to_status', 'delivered')
202:             ->update(['created_at' => now()->subDays(20)]);
203:         $this->storeCreateReturn($customer, $oldOrder, $oldOrder->items->first()->id, 1)
204:             ->assertUnprocessable();
205:     }
