231:     public function test_receive_moves_stock_good_and_damaged_and_computes_refund(): void
232:     {
233:         $variant = $this->purchasableVariant(100);
234:         $level = $this->giveStock($variant, 10);
235:         $customer = Customer::factory()->create();
236:         $order = $this->deliveredOrder($customer, $variant, 3);
237:         $created = $this->storeCreateReturn($customer, $order, $order->items->first()->id, 3)->assertCreated();
238:         $returnId = $created->json('data.id');
239:         $returnItemId = $created->json('data.items.0.id');
240:         $this->assertSame(3, (int) $variant->product->fresh()->sales_count);
241: 
242:         // الاستلام قبل الاعتماد ممنوع
243:         $this->adminPost("/api/v1/admin/returns/{$returnId}/receive", [
244:             'items' => [['id' => $returnItemId, 'received_good_qty' => 1, 'received_damaged_qty' => 0]],
245:         ])->assertUnprocessable();
246: 
247:         $this->adminPost("/api/v1/admin/returns/{$returnId}/approve", [
248:             'branch_id' => $this->branch->id,
249:         ])->assertOk();
250: 
251:         // استلام يتجاوز المعتمد (3) مرفوض
252:         $this->adminPost("/api/v1/admin/returns/{$returnId}/receive", [
253:             'items' => [['id' => $returnItemId, 'received_good_qty' => 3, 'received_damaged_qty' => 1]],
254:         ])->assertUnprocessable();
255: 
256:         $this->adminPost("/api/v1/admin/returns/{$returnId}/receive", [
257:             'items' => [['id' => $returnItemId, 'received_good_qty' => 2, 'received_damaged_qty' => 1]],
258:         ])->assertOk()
259:             ->assertJsonPath('data.status', 'received')
260:             ->assertJsonPath('data.total_refund_amount', '300.00');
261: 
262:         // السليم عاد متاحًا، والتالف محجوز في وعاء التالف، والفعلي زاد بالكل
263:         $branchLevel = $this->branchLevel($variant);
264:         $this->assertNotNull($branchLevel);
265:         $this->assertSame('3.0000', (string) $branchLevel->on_hand);
266:         $this->assertSame('1.0000', (string) $branchLevel->damaged);
267:         $this->assertEquals(2.0, (float) $branchLevel->available);
268:         // مستوى موقع البيع الأصلي لم يتغير بالاستلام
269:         $this->assertSame('7.0000', (string) $level->fresh()->on_hand);
270: 
271:         // الحركات: sale_return للسليم + sale_return وdamage للتالف — كلها بمرجع المرتجع
272:         $movements = StockMovement::query()->where('reference_type', 'return_request')->where('reference_id', $returnId)->get();
273:         $this->assertSame(3, $movements->count());
274:         $this->assertSame(2, $movements->where('type', 'sale_return')->count());
275:         $this->assertSame(1, $movements->where('type', 'damage')->count());
276:         // عدّاد المبيعات تراجع بالكمية المستلمة كلها
277:         $this->assertSame(0, (int) $variant->product->fresh()->sales_count);
278:     }
