280:     public function test_refund_to_wallet_credits_customer_and_completes_order_return_without_double_effects(): void
281:     {
282:         $variant = $this->purchasableVariant(100);
283:         $this->giveStock($variant, 10);
284:         $customer = Customer::factory()->create();
285:         $order = $this->deliveredOrder($customer, $variant, 3);
286:         $created = $this->storeCreateReturn($customer, $order, $order->items->first()->id, 3, [
287:             'refund_method' => 'wallet',
288:         ])->assertCreated();
289:         $returnId = $created->json('data.id');
290:         $returnItemId = $created->json('data.items.0.id');
291: 
292:         // الرد قبل الاستلام ممنوع
293:         $this->adminPost("/api/v1/admin/returns/{$returnId}/refund")->assertUnprocessable();
294: 
295:         $this->adminPost("/api/v1/admin/returns/{$returnId}/approve", ['branch_id' => $this->branch->id])->assertOk();
296:         $this->adminPost("/api/v1/admin/returns/{$returnId}/receive", [
297:             'items' => [['id' => $returnItemId, 'received_good_qty' => 3, 'received_damaged_qty' => 0]],
298:         ])->assertOk();
299:         $stockAfterReceive = (string) $this->branchLevel($variant)->on_hand;
300: 
301:         $this->adminPost("/api/v1/admin/returns/{$returnId}/refund")->assertOk()
302:             ->assertJsonPath('data.status', 'refunded');
303: 
304:         // المحفظة زادت بقيمة المرتجع كاملة
305:         $this->assertSame('300.00', (string) $customer->fresh()->wallet_balance);
306:         // الطلب اكتمل إرجاعه فصارت حالته returned — بلا علم استرداد (الرد تم هنا)
307:         $order = $order->fresh();
308:         $this->assertSame(OrderStatus::Returned, $order->status);
309:         $this->assertFalse((bool) $order->requires_refund);
310:         // وبلا إعادة مخزون ثانية: رصيد ما بعد الرد يساوي رصيد ما بعد الاستلام
311:         $this->assertSame($stockAfterReceive, (string) $this->branchLevel($variant)->on_hand);
312:         $this->assertSame(1, StockMovement::query()->where('reference_type', 'return_request')->where('type', 'sale_return')->count());
313:     }
