186:     // ---------- helpers ----------
187: 
188:     private function postWebhook(string $uri, array $payload, string $secret): TestResponse
189:     {
190:         $body = json_encode($payload);
191: 
192:         return $this->call('POST', $uri, [], [], [], [
193:             'HTTP_X-Webhook-Signature' => hash_hmac('sha256', $body, $secret),
194:             'CONTENT_TYPE' => 'application/json',
195:             'HTTP_ACCEPT' => 'application/json',
196:         ], $body);
197:     }
198: 
199:     private function makeOrder(ProductVariant $variant, float|int $qty, string $paymentMethod): Order
200:     {
201:         $cart = Cart::create([]);
202:         $cart->items()->create(['product_variant_id' => $variant->id, 'qty' => $qty]);
203: 
204:         return app(OrderService::class)->createFromCart($cart, [
205:             'recipient_name' => 'عميل', 'recipient_phone' => '01012345678',
206:             'payment_method' => $paymentMethod,
207:         ]);
208:     }
209: 
210:     private function purchasableVariant(float $price): ProductVariant
211:     {
212:         $product = Product::factory()->create(['status' => 'published']);
213: 
214:         return ProductVariant::factory()->create([
215:             'product_id' => $product->id,
216:             'retail_price' => $price,
217:         ]);
218:     }
219: 
220:     private function giveStock(ProductVariant $variant, float|int $qty): void
221:     {
222:         app(InventoryService::class)->recordMovement([
223:             'product_variant_id' => $variant->id,
224:             'branch_id' => $this->branch->id,
225:             'type' => StockMovementType::AdjustmentIn,
226:             'affected_bucket' => StockBucket::OnHand,
227:             'quantity' => $qty,
228:             'created_by' => $this->staff->id,
229:         ]);
230:     }
231: 
232:     private function level(int $variantId): StockLevel
233:     {
234:         return StockLevel::query()
235:             ->where('product_variant_id', $variantId)
236:             ->where('branch_id', $this->branch->id)
237:             ->whereNull('location_id')
238:             ->firstOrFail();
239:     }
