 7: /**
 8:  * بصمة حمولات عدم التكرار: ترتيب حتمي لمفاتيح المصفوفات وتطبيع للأرقام،
 9:  * بحيث تنتج الاختلافات الشكلية في تسلسل العميل ("5" مقابل 5 مقابل 5.0)
10:  * نفس البصمة، فلا تتحول إعادة إرسال مطابقة إلى 409 زائف (L-2).
11:  */
12: final class IdempotencyFingerprint
13: {
14:     public static function hash(array $payload): string
15:     {
16:         return hash('sha256', json_encode(self::canonicalize($payload), JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION));
17:     }
18: 
19:     private static function canonicalize(mixed $value, ?string $field = null): mixed
20:     {
21:         if (is_string($value) && is_numeric($value)
22:             && ($field === 'id' || str_ends_with($field ?? '', '_id')
23:                 || in_array($field, ['qty', 'amount', 'received_good_qty', 'received_damaged_qty', 'quantity', 'requested_qty', 'counted_qty', 'approved_qty', 'shipped_qty', 'received_qty'], true))) {
24:             $value = $value + 0;
25:         }
26: 
27:         if (is_float($value) && floor($value) === $value && abs($value) <= 9007199254740991) {
28:             return (int) $value;
29:         }
30: 
31:         if (! is_array($value)) {
32:             return $value;
33:         }
34: 
35:         $isList = array_is_list($value);
36:         $mapped = [];
37:         foreach ($value as $key => $item) {
38:             $mapped[$key] = self::canonicalize($item, is_string($key) ? $key : null);
39:         }
40: 
41:         if (! $isList) {
42:             ksort($mapped);
43:         }
44: 
45:         return $mapped;
46:     }
47: }  1: <?php
