 63:     public function setEmailAttribute(?string $email): void
 64:     {
 65:         $normalized = $email === null ? null : mb_strtolower(trim($email));
 66:         if (($this->attributes['email'] ?? null) !== $normalized) {
 67:             $this->attributes['email_verified_at'] = null;
 68:         }
 69:         $this->attributes['email'] = $normalized;
