 77:     public static function normalizePhone(string $phone): string
 78:     {
 79:         $phone = strtr(trim($phone), array_combine(
 80:             preg_split('//u', '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹', -1, PREG_SPLIT_NO_EMPTY),
 81:             str_split('01234567890123456789'),
 82:         ));
 83:         $phone = preg_replace('/[\s().-]+/u', '', $phone);
 84:         if (str_starts_with($phone, '+20')) {
 85:             return '0'.substr($phone, 3);
 86:         }
 87:         if (str_starts_with($phone, '0020')) {
 88:             return '0'.substr($phone, 4);
 89:         }
 90: 
 91:         return $phone;
 92:     }
