  7: use App\Enums\OrderStatus;
  8: use App\Models\Order;
  9: use App\Models\WebhookLog;
 10: use Illuminate\Database\DeadlockException;
 11: use Illuminate\Support\Facades\DB;
 12: use Illuminate\Support\Facades\Log;
 13: use Throwable;
 14: 
 15: /**
 16:  * معالجة ويب هوك بوابات الدفع:
 17:  * تسجيل أولًا ← تحقق HMAC ← معالجة ذرّية داخل transaction بقفل استشاري
 18:  * على (provider, event) لمنع المعالجة المكررة المتزامنة (H4) ←
 19:  * التحقق من المبلغ والعملة مقابل إجمالي الطلب (H5) ← تحديث حالة الدفع
 20:  * وتأكيد الطلب تلقائيًا عبر OrderService عند النجاح.
 21:  */
 22: class PaymentWebhookService
 23: {
 24:     private const SUCCESS = ['paid', 'success', 'successful', 'succeeded', 'captured', 'completed', 'approved'];
 25: 
 26:     private const FAILED = ['failed', 'voided', 'declined', 'error', 'cancelled', 'canceled'];
 27: 
 28:     public function __construct(
 29:         protected WebhookSignatureVerifier $verifier,
 30:         protected OrderService $orders,
 31:     ) {}
 32: 
 33:     /**
 34:      * @param  array<string, string|null>  $headers
 35:      * @param  array<string, mixed>  $query
 36:      * @return array{http: int, body: array<string, mixed>}
 37:      */
 38:     public function handle(string $gateway, array $payload, string $rawBody, array $headers, array $query, ?string $ip): array
 39:     {
 40:         $provider = 'payment:'.$gateway;
 41:         // قبل التحقق لا يُوثق بأي حقل من الحمولة (F-07): مفتاح السجل
 42:         // المختصر هو بصمة الجسم فقط، وأي معرّف من الحمولة قد يكون مصفوفة
 43:         // تكسر (string) أو نصًا أطول من عمود السجل فيحوّل الهجوم لـ 500
 44:         $preVerifyKey = 'sha256:'.hash('sha256', $rawBody);
 45: 
 46:         // حد حجم الجسم أولًا — الرفض بسجل مختصر بلا حمولة (M4)
 47:         if (strlen($rawBody) > 262144) {
 48:             $this->slimLog($provider, $preVerifyKey, 'rejected', 'payload too large', $ip);
 49: 
 50:             return ['http' => 413, 'body' => ['received' => false, 'message' => 'payload too large']];
 51:         }
 52: 
 53:         $config = config("webhooks.payment.{$gateway}");
 54:         if (! is_array($config)) {
 55:             $this->slimLog($provider, $preVerifyKey, 'failed', 'بوابة دفع غير معروفة', $ip);
 56: 
 57:             return ['http' => 404, 'body' => ['received' => false, 'message' => 'unknown gateway']];
 58:         }
 59: 
 60:         // Paymob (C1): توقيعه يغطي حقول obj المحددة فقط، فكل قرار (الحالة،
 61:         // المبلغ، المعرّف، ربط الطلب) يجب أن يُشتق من obj وحدها — لا من حقول
 62:         // أعلى المستوى غير الموقّعة (order_number/amount/event_id).
 63:         $isPaymob = (string) ($config['driver'] ?? 'hmac') === 'paymob';
 64: 
 65:         // التحقق بنمط البوابة (F-06) قبل تخزين الحمولة: محاولات مجهولة
 66:         // لا تملأ webhook_logs.payload — تُسجل مختصرة فقط (M4)
 67:         $verified = $this->verifier->verifyGateway(
 68:             (string) ($config['driver'] ?? 'hmac'),
 69:             $config['secret'] ?? null,
 70:             $rawBody,
 71:             $headers,
 72:             $query,
 73:             $payload,
 74:             $config['signature_header'] ?? null,
 75:         );
 76:         if (! $verified) {
 77:             $this->slimLog($provider, $preVerifyKey, 'invalid_signature', null, $ip);
 78: 
 79:             return ['http' => 403, 'body' => ['received' => false, 'message' => 'invalid signature']];
 80:         }
 81: 
 82:         // بعد التحقق فقط: معرّف الحدث من الحمولة مُنقّى (قيمة مفردة وحد
 83:         // طول) ومدموجًا بنتيجة الحدث (F-08) حتى لا يبتلع الاستردادَ حدثُ
 84:         // الدفعِ لنفس المعاملة فيُعلَّم duplicate
 85:         $outcome = $isPaymob ? $this->paymobOutcome($payload) : $this->outcome($payload);
 86:         $extractedId = $isPaymob ? $this->paymobEventId($payload) : $this->extractEventId($payload);
 87:         $eventId = $extractedId !== null ? $extractedId.':'.$outcome : $preVerifyKey;
 88: 
 89:         $log = $this->startLog($provider, $eventId, $payload, $ip);
 90:         $log->update(['signature_valid' => true]);
 91: 
 92:         return DB::transaction(function () use ($gateway, $provider, $eventId, $payload, $log, $config, $outcome, $isPaymob): array {
 93:             // قفل استشاري على مفتاح الحدث: نسختان متزامنتان من نفس الحدث تتسلسلان هنا
 94:             DB::statement('SELECT pg_advisory_xact_lock(hashtext(?))', [$provider.':'.$eventId]);
 95: 
 96:             if ($this->alreadyProcessed($provider, $log)) {
 97:                 $log->update(['status' => 'duplicate']);
 98: 
 99:                 return ['http' => 200, 'body' => ['received' => true, 'duplicate' => true]];
100:             }
101: 
102:             // ربط الطلب (C1): لـ Paymob من obj.order.id الموقّع مقابل
103:             // orders.gateway_order_id، ولباقي البوابات من حقولها المعتادة
104:             $orderReference = $isPaymob
105:                 ? $this->paymobGatewayOrderId($payload)
106:                 : $this->extractOrderNumber($payload);
107:             $order = $orderReference !== null
108:                 ? Order::query()
109:                     ->when($isPaymob,
110:                         fn ($q) => $q->where('gateway_order_id', $orderReference),
111:                         fn ($q) => $q->where('order_number', $orderReference))
112:                     ->lockForUpdate()->first()
113:                 : null;
114:             if ($order === null) {
115:                 $log->update(['status' => 'failed', 'error' => 'طلب غير موجود: '.($orderReference ?? '—')]);
116: 
117:                 return ['http' => 200, 'body' => ['received' => false, 'message' => 'order not found']];
118:             }
119: 
120:             if ($order->payment_method === 'wallet') {
121:                 $log->update(['status' => 'ignored', 'error' => 'Wallet payments are settled internally.']);
122: 
123:                 return ['http' => 200, 'body' => ['received' => true, 'ignored' => true]];
124:             }
125: 
126:             if ($outcome === 'ignored' || $outcome === 'pending') {
127:                 $log->update([
128:                     'status' => 'ignored',
129:                     'error' => $outcome === 'pending' ? 'معاملة معلقة لدى البوابة (pending)' : 'حالة دفع غير معروفة في الحمولة',
130:                 ]);
131: 
132:                 return ['http' => 200, 'body' => ['received' => true, 'ignored' => true]];
133:             }
134: 
135:             // التحقق من المبلغ والعملة قبل أي تغيير (H5) — ولـ Paymob من
136:             // obj.amount_cents/obj.currency الموقّعين فقط (C1)
137:             $amountOk = $isPaymob
138:                 ? $this->paymobAmountMatches($payload, $order, $config)
139:                 : $this->amountMatches($payload, $order, $config);
140:             if ($outcome === 'paid' && ! $amountOk) {
141:                 // المال قد يكون قُبض فعلًا مع مبلغ مخالف: يُعلَّم الطلب للانتباه
142:                 // ويُنبَّه السجل — لا يُكتفى بسجل failed صامت (F-22)
