146:                     'order_id' => $order->id,
147:                     'order_number' => $order->order_number,
148:                     'gateway' => $gateway,
149:                     'expected' => (string) $order->grand_total,
150:                 ]);
151: 
152:                 return ['http' => 200, 'body' => ['received' => false, 'message' => 'amount mismatch']];
153:             }
154: 
155:             $note = null;
156:             if ($outcome === 'paid') {
157:                 if ($order->status === OrderStatus::Cancelled) {
158:                     // مال قُبض على طلب ملغي: يُثبت الدفع ويُعلَّم للاسترداد، ولا يُحيى الطلب
159:                     $order->update(['payment_status' => 'paid', 'requires_refund' => true]);
160:                     $note = 'دفع ناجح على طلب ملغي — يحتاج استردادًا';
161:                 } else {
162:                     $order->update(['payment_status' => 'paid']);
163:                     if ($order->status === OrderStatus::Pending) {
164:                         try {
165:                             $this->orders->changeStatus($order, OrderStatus::Confirmed, null, "تأكيد تلقائي بعد نجاح الدفع عبر {$gateway}");
166:                         } catch (DeadlockException $e) {
167:                             // جمود قفل: يُعاد رميه ليُعيد الوسيط المحاولة، ولا يُبتلع
168:                             // كـ «دُفع ولم يُؤكَّد» فيفقد الحدث أثره (F12)
169:                             throw $e;
170:                         } catch (Throwable $e) {
171:                             // «دُفع ولم يُؤكَّد» حالة تشغيلية خطيرة: تنبيه سجل +
172:                             // علامة ظاهرة في شاشة الطلب بدل دفنها في الويب هوك (M19)
173:                             Log::warning('Payment captured but order auto-confirm failed.', [
174:                                 'order_id' => $order->id,
175:                                 'order_number' => $order->order_number,
176:                                 'gateway' => $gateway,
177:                                 'exception' => $e->getMessage(),
178:                             ]);
179:                             $order->update(['needs_attention' => true]);
180:                             $note = 'تم الدفع لكن تأكيد الطلب فشل: '.$e->getMessage();
181:                         }
182:                     }
183:                 }
184:             } elseif ($outcome === 'failed') {
185:                 if ($order->payment_status === 'paid') {
