187:                     $log->update(['status' => 'ignored', 'error' => 'حدث فشل متأخر بعد دفع ناجح — يُتجاهل']);
188: 
189:                     return ['http' => 200, 'body' => ['received' => true, 'ignored' => true]];
190:                 }
