217:     private function outcome(array $payload): string
218:     {
219:         // معاملة معلقة (Paymob: success=false مع pending=true) ليست فشلًا
220:         $pending = data_get($payload, 'obj.pending') ?? data_get($payload, 'data.pending') ?? data_get($payload, 'pending');
221:         if ($pending === true) {
222:             return 'pending';
223:         }
224: 
225:         $successFlag = data_get($payload, 'obj.success') ?? data_get($payload, 'data.success') ?? data_get($payload, 'success');
226:         if (is_bool($successFlag)) {
227:             return $successFlag ? 'paid' : 'failed';
228:         }
229: 
230:         $status = strtolower((string) ($this->firstValue($payload, [
231:             'status', 'payment_status', 'data.status',
232:             'data.object.payment_status', 'data.object.status', 'obj.status', 'state',
233:         ]) ?? ''));
234:         if (in_array($status, self::SUCCESS, true)) {
235:             return 'paid';
236:         }
237:         if ($status === 'refunded' || $status === 'refund') {
238:             return 'refunded';
239:         }
240:         if (in_array($status, self::FAILED, true)) {
241:             return 'failed';
242:         }
243: 
244:         // حدث Stripe بنيوي: النوع (type) هو مصدر الحالة، وليس status
245:         // (F10) — charge.refunded / payment_intent.succeeded / *.failed
246:         $type = strtolower((string) ($this->firstValue($payload, ['type', 'event_type', 'event']) ?? ''));
247:         if ($type !== '') {
248:             if (str_contains($type, 'refund')) {
249:                 return 'refunded';
250:             }
251:             if (str_contains($type, 'fail') || str_contains($type, 'declin')) {
252:                 return 'failed';
253:             }
254:             if (str_contains($type, 'succeeded') || str_contains($type, 'completed')
255:                 || str_contains($type, 'captured') || str_contains($type, 'paid')) {
256:                 return 'paid';
257:             }
258:         }
259: 
260:         return 'ignored';
261:     }
262: 
263:     /**
264:      * مقارنة مبلغ الحدث بإجمالي الطلب وعملته. إن لم يحمل الحدث مبلغًا
265:      * يُقبل (بعض البوابات لا ترسله) — وإن حمله واختلف يُرفض.
266:      *
267:      * @param  array<string, mixed>  $config
268:      */
269:     private function amountMatches(array $payload, Order $order, array $config): bool
270:     {
271:         $expectedCurrency = strtoupper((string) ($config['currency'] ?? 'EGP'));
272:         $currency = $this->firstValue($payload, [
273:             'currency', 'data.currency', 'data.object.currency', 'obj.currency', 'obj.order.currency',
274:         ]);
275:         if ($currency !== null && strtoupper((string) $currency) !== $expectedCurrency) {
276:             return false;
277:         }
278: 
279:         $amount = $this->firstValue($payload, [
280:             'amount', 'data.amount', 'data.object.amount', 'data.object.amount_total',
281:             'data.object.amount_received', 'obj.amount', 'obj.order.amount',
282:         ]);
283:         $divisor = (float) ($config['amount_divisor'] ?? 1);
284:         if ($amount === null) {
285:             $cents = $this->firstValue($payload, [
286:                 'amount_cents', 'data.amount_cents', 'data.object.amount_total',
287:                 'data.object.amount_received', 'obj.amount_cents', 'obj.order.amount_cents',
288:             ]);
289:             if ($cents !== null) {
290:                 $amount = $cents;
291:                 $divisor = 100.0;
292:             }
293:         }
294:         if ($amount === null) {
295:             // بوابة تُعلن وجوب وجود المبلغ (F10): حدث ناجح بلا مبلغ لا يُقبل
296:             return ! ($config['require_amount'] ?? false);
297:         }
298: 
299:         return abs(round(((float) $amount) / $divisor, 2) - (float) $order->grand_total) < 0.01;
300:     }
