302:     private function extractOrderNumber(array $payload): ?string
303:     {
304:         $value = $this->firstValue($payload, [
305:             'order_number', 'merchant_order_id', 'data.order_number',
306:             'data.object.metadata.order_number', 'data.object.client_reference_id',
307:             'obj.order.merchant_order_id', 'obj.merchant_order_id', 'metadata.order_number',
308:         ]);
309: 
310:         // قيم غير مفردة (مصفوفات) لا تُحوَّل لنص — تُتجاهل (F-07)
311:         return is_scalar($value) ? mb_substr((string) $value, 0, 191) : null;
312:     }
