315:     {
316:         $value = $this->firstValue($payload, [
317:             'event_id', 'transaction_id', 'obj.id', 'data.id', 'data.transaction_id',
318:             'data.object.id', 'id',
319:         ]);
320: 
321:         return is_scalar($value) ? mb_substr((string) $value, 0, 191) : null;
322:     }
