324:     /** كائن معاملة Paymob الموقّع (obj) — مصدر الحقيقة الوحيد لبوابة Paymob. */
325:     private function paymobObj(array $payload): ?array
326:     {
327:         $obj = $payload['obj'] ?? null;
328: 
329:         return is_array($obj) ? $obj : null;
330:     }
331: 
332:     /**
333:      * حالة حدث Paymob من الحقول الموقّعة فقط (C1): علم الاسترداد/الإلغاء
334:      * يُفحص قبل success لأن Paymob يرسل success=true مع is_refunded/is_voided
335:      * فيُصنّف الاسترداد خطأً كدفع ناجح إن فُحص success أولًا.
336:      */
337:     private function paymobOutcome(array $payload): string
338:     {
339:         $obj = $this->paymobObj($payload);
340:         if ($obj === null) {
341:             return 'ignored';
342:         }
343: 
344:         if ($this->paymobFlag($obj, 'is_refunded') || $this->paymobFlag($obj, 'is_voided')) {
345:             return 'refunded';
346:         }
347:         if ($this->paymobFlag($obj, 'pending')) {
348:             return 'pending';
349:         }
350: 
351:         $success = $obj['success'] ?? null;
352:         if ($success === true || $success === 'true' || $success === 1 || $success === '1') {
353:             return 'paid';
354:         }
355:         if ($success === false || $success === 'false' || $success === 0 || $success === '0') {
356:             return 'failed';
357:         }
358: 
359:         return 'ignored';
360:     }
