362:     /** معرّف حدث Paymob: obj.id الموقّع (لا event_id أعلى المستوى غير الموقّع). */
363:     private function paymobEventId(array $payload): ?string
364:     {
365:         $obj = $this->paymobObj($payload);
366:         $id = $obj['id'] ?? null;
367: 
368:         return is_scalar($id) && $id !== '' ? mb_substr((string) $id, 0, 191) : null;
369:     }
