371:     /** معرّف طلب Paymob الموقّع (obj.order.id) لربط الطلب. */
372:     private function paymobGatewayOrderId(array $payload): ?string
373:     {
374:         $obj = $this->paymobObj($payload);
375:         $id = is_array($obj['order'] ?? null) ? ($obj['order']['id'] ?? null) : null;
