380:     /**
381:      * مطابقة المبلغ والعملة لـ Paymob من obj.amount_cents وobj.currency فقط
382:      * (C1) — لا من amount/currency أعلى المستوى غير الموقّعين.
383:      *
384:      * @param  array<string, mixed>  $config
385:      */
386:     private function paymobAmountMatches(array $payload, Order $order, array $config): bool
387:     {
388:         $obj = $this->paymobObj($payload);
389:         if ($obj === null) {
390:             return false;
391:         }
392: 
393:         $expectedCurrency = strtoupper((string) ($config['currency'] ?? 'EGP'));
394:         $currency = $obj['currency'] ?? null;
395:         if (! is_scalar($currency) || strtoupper((string) $currency) !== $expectedCurrency) {
396:             return false;
397:         }
398: 
399:         $cents = $obj['amount_cents'] ?? null;
400:         if (! is_numeric($cents)) {
401:             return ! ($config['require_amount'] ?? false);
402:         }
403: 
404:         return abs(round(((float) $cents) / 100, 2) - (float) $order->grand_total) < 0.01;
405:     }
