 39:     /**
 40:      * Return all settings grouped by their group name, with values cast to their declared types.
 41:      * Numbering counters are read fresh because they change for every generated document number.
 42:      *
 43:      * @return array<string, array<string, mixed>>
 44:      */
 45:     public function getAllGrouped(): array
 46:     {
 47:         $grouped = Cache::remember(self::CACHE_KEY, self::CACHE_TTL_SECONDS, function (): array {
 48:             return Setting::query()
 49:                 ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
 50:                 ->orderBy('group')
 51:                 ->orderBy('key')
 52:                 ->get()
 53:                 ->groupBy('group')
 54:                 ->map(fn ($settings): array => $settings
 55:                     ->mapWithKeys(fn (Setting $setting): array => [
 56:                         $setting->key => $this->castValue($setting->value, $setting->type),
 57:                     ])
 58:                     ->all())
 59:                 ->all();
 60:         });
 61: 
 62:         $counters = Setting::query()
 63:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
 64:             ->orderBy('key')
 65:             ->get()
 66:             ->mapWithKeys(fn (Setting $setting): array => [
 67:                 $setting->key => $this->castValue($setting->value, $setting->type),
 68:             ])
 69:             ->all();
 70: 
 71:         if (isset($counters['movement_next_number'])) {
 72:             $counters['movement_next_number'] = $this->nextMovementNumber();
 73:         }
 74: 
 75:         if ($counters !== []) {
 76:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
 77:             ksort($grouped['numbering']);
 78:         }
 79: 
 80:         return $grouped;
 81:     }
