104:             $movementSequenceTarget = null;
105:             $lockedSettings = Setting::query()
106:                 ->whereIn('key', array_keys($settings))
107:                 ->orderBy('key')
108:                 ->lockForUpdate()
109:                 ->get()
110:                 ->keyBy('key');
111: 
112:             $missingKeys = array_diff(array_keys($settings), $lockedSettings->keys()->all());
113: 
114:             if ($missingKeys !== []) {
115:                 throw new InvalidArgumentException('Settings are not initialized: '.implode(', ', $missingKeys));
116:             }
117: 
118:             foreach ($settings as $key => $value) {
119:                 /** @var Setting $setting */
120:                 $setting = $lockedSettings->get($key);
121: 
122:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
123:                     $value = max($this->counterValue($setting->value), $this->counterValue($value));
124:                     if ($key === 'movement_next_number') {
125:                         $value = max($value, $this->nextMovementNumber());
126:                         $movementSequenceTarget = $value;
127:                     }
128:                 }
129: 
130:                 $setting->value = $value === null && str_ends_with($key, '_prefix')
131:                     ? ''
132:                     : $this->serializeValue($value, $setting->type);
133:                 $setting->save();
134:             }
135: 
136:             DB::afterCommit(fn () => $this->clearCache());
137: 
138:             if ($movementSequenceTarget !== null) {
139:                 // مزامنة التسلسل بعد الاعتماد لا داخله: ALTER SEQUENCE داخل
140:                 // المعاملة كان يحجب كل nextval (أي كل حركات المخزون) حتى نهاية
141:                 // معاملة الإعدادات (L-9). الدالة تقفل الترقيم لمدة الاستعلام
142:                 // نفسه وتنسّق رفع الحد الأدنى مع كل تخصيص جديد لمنع إعادة رقم.
143:                 DB::afterCommit(function () use ($movementSequenceTarget): void {
144:                     DB::selectOne('SELECT inventory_movement_number(?) AS number', [$movementSequenceTarget]);
145:                 });
146:             }
147:         }, attempts: 3);
148:     }
