150:     /**
151:      * Atomically return and increment the next document number for the requested type.
152:      *
153:      * @throws JsonException
154:      */
155:     public function generateNextNumber(string $type): string
156:     {
157:         if ($type === 'movement') {
158:             [$prefix, $padding] = $this->numberingConfig('movement', 'movement_prefix', 'movement_padding');
159:             $number = DB::selectOne('SELECT inventory_movement_number() AS number')->number;
160: 
161:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
162:         }
163:         $definitions = [
164:             'invoice' => ['prefix' => 'invoice_prefix', 'next' => 'invoice_next_number', 'padding' => 'invoice_padding'],
165:             'order' => ['prefix' => 'order_prefix', 'next' => 'order_next_number', 'padding' => 'order_padding'],
166:             'purchase_order' => ['prefix' => 'purchase_order_prefix', 'next' => 'purchase_order_next_number', 'padding' => 'purchase_order_padding'],
167:             'quotation' => ['prefix' => 'quotation_prefix', 'next' => 'quotation_next_number', 'padding' => 'quotation_padding'],
168:             'transfer' => ['prefix' => 'transfer_prefix', 'next' => 'transfer_next_number', 'padding' => 'transfer_padding'],
169:             'stocktake' => ['prefix' => 'stocktake_prefix', 'next' => 'stocktake_next_number', 'padding' => 'stocktake_padding'],
170:             'return' => ['prefix' => 'return_prefix', 'next' => 'return_next_number', 'padding' => 'return_padding'],
171:             'purchase_request' => ['prefix' => 'purchase_request_prefix', 'next' => 'purchase_request_next_number', 'padding' => 'purchase_request_padding'],
172:             'delivery' => ['prefix' => 'delivery_prefix', 'next' => 'delivery_next_number', 'padding' => 'delivery_padding'],
173:             'supplier_invoice' => ['prefix' => 'supplier_invoice_prefix', 'next' => 'supplier_invoice_next_number', 'padding' => 'supplier_invoice_padding'],
174:             'supplier_payment' => ['prefix' => 'supplier_payment_prefix', 'next' => 'supplier_payment_next_number', 'padding' => 'supplier_payment_padding'],
175:         ];
176: 
177:         if (! isset($definitions[$type])) {
178:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
179:         }
180: 
181:         $definition = $definitions[$type];
182:         [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
183: 
184:         return DB::transaction(function () use ($definition, $prefix, $padding): string {
185:             // العداد وحده يُقفل ويُقرأ طازجًا كل مرة؛ البادئة والحشو من ذاكرة الطلب.
186:             $nextSetting = Setting::query()
187:                 ->where('key', $definition['next'])
188:                 ->lockForUpdate()
189:                 ->first();
190: 
191:             if ($nextSetting === null) {
192:                 throw new InvalidArgumentException("Required numbering setting [{$definition['next']}] is missing.");
193:             }
194: 
195:             $nextValue = $this->counterValue($nextSetting->value);
196: 
197:             $formatted = $prefix.str_pad((string) $nextValue, $padding, '0', STR_PAD_LEFT);
198:             $nextSetting->value = (string) ($nextValue + 1);
199:             $nextSetting->save();
200: 
201:             return $formatted;
202:         }, attempts: 3);
203:     }
204: 
205:     /**
206:      * بادئة وحشو نوع ترقيم — قراءة واحدة لكل طلب بدل استعلام مع كل حركة/مستند.
207:      *
208:      * @return array{0: string, 1: int}
209:      */
210:     private function numberingConfig(string $type, string $prefixKey, string $paddingKey): array
211:     {
212:         return $this->numberingConfig[$type] ??= (function () use ($prefixKey, $paddingKey): array {
213:             $settings = Setting::query()->whereIn('key', [$prefixKey, $paddingKey])->pluck('value', 'key');
214: 
215:             foreach ([$prefixKey, $paddingKey] as $key) {
216:                 if (! $settings->has($key)) {
217:                     throw new InvalidArgumentException("Required numbering setting [{$key}] is missing.");
218:                 }
219:             }
220: 
221:             return [(string) $settings[$prefixKey], max(0, (int) $settings[$paddingKey])];
222:         })();
223:     }
224: 
225:     public function clearCache(): void
226:     {
227:         Cache::forget(self::CACHE_KEY);
228:         $this->numberingConfig = [];
229:     }
230: 
231:     private function nextMovementNumber(): int
232:     {
233:         $sequence = DB::selectOne('SELECT last_value, is_called FROM stock_movement_number_seq');
234: 
235:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
236:     }
237: 
238:     private function counterValue(mixed $value): int
239:     {
240:         $number = (is_int($value) || is_string($value))
241:             ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => PHP_INT_MAX - 1]])
242:             : false;
243:         if ($number === false) {
244:             throw new BusinessException('قيمة عداد الترقيم يجب أن تكون عددًا صحيحًا موجبًا ضمن النطاق المسموح');
245:         }
246: 
247:         return $number;
248:     }
249: 
250:     private function castValue(?string $value, string $type): mixed
251:     {
252:         if ($value === null) {
253:             return null;
254:         }
255: 
256:         return match ($type) {
257:             'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
258:             'integer' => (int) $value,
259:             'float' => (float) $value,
260:             'json' => json_decode($value, true, 512, JSON_THROW_ON_ERROR),
261:             default => $value,
262:         };
263:     }
264: 
265:     /** @throws JsonException */
266:     private function serializeValue(mixed $value, string $type): ?string
267:     {
268:         if ($value === null) {
269:             return null;
270:         }
271: 
272:         if ($type === 'json') {
273:             return json_encode($value, JSON_THROW_ON_ERROR);
274:         }
275: 
276:         if ($type === 'boolean') {
277:             return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
278:         }
279: 
280:         return (string) $value;
281:     }
