262:                 'channel' => $data['channel'] ?? 'store',
263:                 'customer_id' => $customer?->id,
264:                 'guest_name' => $data['recipient_name'] ?? $customer?->name,
265:                 'guest_phone' => $data['recipient_phone'] ?? $customer?->phone,
266:                 'guest_phone_normalized' => $guestPhoneNormalized,
267:                 'guest_email' => $data['recipient_email'] ?? $customer?->email,
268:                 'city_id' => $city?->id,
269:                 'shipping_address_line' => $data['shipping_address_line'] ?? null,
270:                 'shipping_notes' => $data['shipping_notes'] ?? null,
271:                 'status' => OrderStatus::Pending,
272:                 'payment_method' => $data['payment_method'] ?? 'cod',
273:                 'payment_status' => 'unpaid',
274:                 'subtotal' => $subtotal,
275:                 'discount_amount' => $discountAmount,
276:                 'coupon_id' => $couponId,
277:                 'coupon_code' => $couponCode,
278:                 'shipping_cost' => $shippingCost,
279:                 'cod_fee' => $codFee,
280:                 'tax_amount' => $taxAmount,
281:                 'grand_total' => $grandTotal,
282:             ]);
283: 
284:             // بنود الطلب بلقطات الاسم والـ SKU والسعر + توزيع الضريبة وحصة
285:             // الكوبون على البنود بطريقة «أكبر باقٍ» (L5/M17): الحصة تُحسب
286:             // بالقروش فتكون الأعداد صحيحة ومجموعها يساوي الإجمالي بالضبط،
287:             // ولا يقع بند بحصة سالبة بسبب التقريب
288:             $weights = array_map(fn (array $line): float => (float) $line['line_total'], $lines);
289:             $taxShares = $this->distributeLargestRemainder($taxAmount, $weights);
290:             $couponShares = $this->distributeLargestRemainder($couponDiscount, $weights);
291:             foreach ($lines as $i => $line) {
292:                 $order->items()->create([
293:                     'product_variant_id' => $line['variant']->id,
294:                     'product_name_snapshot' => $line['variant']->product?->name_ar ?? '',
295:                     'sku_snapshot' => $line['variant']->sku,
296:                     'qty' => $line['qty'],
297:                     'unit_price' => $line['unit_price'],
298:                     'discount_amount' => round($line['line_discount'] + $couponShares[$i], 2),
299:                     'tax_amount' => $taxShares[$i],
300:                     'line_total' => $line['line_total'],
301:                 ]);
302:             }
303: 
304:             // الحجز الفوري داخل نفس معاملة الشراء (F-01): التوفر يتحول
305:             // لحجز ذرّي تحت أقفال صفوف الأرصدة بدل انتظار التأكيد، فآخر
306:             // وحدة لا تُباع مرتين. نقص الرصيد يُسقط الشراء كله هنا.
307:             $order->load('items');
308:             $this->allocationService->allocate($order, performedBy: $this->inventoryActorId($customer));
309:             $order->refresh();
310: 
311:             // تسجيل استخدام الكوبون فعليًا (خصم البضاعة أو الشحن المُعفى).
312:             // كوبون شحن مجاني وشحن الطلب صفر أصلًا لا يستهلك حدًا بلا فائدة (L4)
313:             if ($coupon !== null
314:                 && ! ($coupon->type === 'free_shipping' && $waivedShipping <= 0)) {
315:                 $this->couponService->recordUsage(
316:                     $coupon,
317:                     $order,
318:                     $customer,
319:                     $coupon->type === 'free_shipping' ? $waivedShipping : $couponDiscount,
320:                 );
321:             }
322: 
323:             if (($data['payment_method'] ?? 'cod') === 'wallet') {
324:                 if ($customer === null || $customer->fresh()->status !== CustomerStatus::Approved) {
325:                     throw new BusinessException('الدفع بالمحفظة يتطلب حساب عميل نشطًا.');
326:                 }
327:                 app(WalletService::class)->record($customer->id, -$grandTotal, 'checkout_payment', 'order', $order->id);
328:                 $order->update(['payment_status' => 'paid']);
329:             }
330: 
331:             // أول سجل حالة: إنشاء الطلب
332:             $order->statusHistories()->create([
333:                 'from_status' => null,
334:                 'to_status' => OrderStatus::Pending,
335:                 'changed_by_type' => $customer?->getMorphClass(),
336:                 'changed_by_id' => $customer?->getKey(),
337:                 'notes' => 'تم إنشاء الطلب من السلة',
338:             ]);
339: 
340:             // إفراغ السلة من البنود التي تحولت لطلب فقط (F-23): بند أُضيف
341:             // والتزم أثناء المعاملة لا يجب أن يمسحه مسحٌ كامل للسلة
342:             $orderedItemIds = array_values(array_unique(array_map(
343:                 fn (array $line): int => (int) $line['item_id'],
344:                 $lines,
345:             )));
346:             if ($orderedItemIds !== []) {
347:                 $cart->items()->whereIn('id', $orderedItemIds)->delete();
348:             }
349:             $cart->update(['coupon_id' => null]);
350: 
351:             return $order->fresh(['items', 'statusHistories']);
352:         });
353:     }
354: 
355:     /**
356:      * بوابة الحالة الوحيدة. $expectedFrom (F-11): حالات مصدر يفترضها
357:      * المستدعي على نسخته غير المقفولة — تُفحص بعد إعادة القراءة بالقفل،
358:      * فسباق (عميل يلغي × أدمن يجهّز) لا يمر من فحص قديم.
359:      * $returnEffects (المرحلة 9): عند false ينتقل الطلب إلى Returned بلا
360:      * إعادة مخزون وبلا علم استرداد — مسار RMA سوّى المخزون عند الاستلام
361:      * الفعلي والمال عند رد المبلغ، فتكرار الأثر هنا ازدواج.
362:      *
363:      * @param  array<int, OrderStatus>|null  $expectedFrom
364:      */
365:     public function changeStatus(Order $order, OrderStatus|string $toStatus, ?Model $actor = null, ?string $notes = null, ?array $expectedFrom = null, bool $returnEffects = true): Order
366:     {
367:         $to = $toStatus instanceof OrderStatus ? $toStatus : OrderStatus::from($toStatus);
368: 
369:         return DB::transaction(function () use ($order, $to, $actor, $notes, $expectedFrom, $returnEffects): Order {
370:             // إعادة قراءة الطلب بقفل صف: النسخة الممرَّرة قد تكون قديمة،
371:             // وكل الانتقالات على نفس الطلب يجب أن تتسلسل (C1)
372:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
373:             $from = $order->status;
374: 
375:             if ($expectedFrom !== null && ! in_array($from, $expectedFrom, true)) {
376:                 throw new BusinessException("تغيّرت حالة الطلب أثناء العملية (أصبحت {$from->value})؛ أعد المحاولة.");
377:             }
378: 
379:             if ($from === $to) {
380:                 return $order;
381:             }
382: 
383:             if (! in_array($to->value, self::TRANSITIONS[$from->value] ?? [], true)) {
384:                 throw new BusinessException("انتقال حالة غير مسموح: من ({$from->value}) إلى ({$to->value}).");
385:             }
386: 
387:             $actorId = $this->inventoryActorId($actor);
388: 
389:             if ($to === OrderStatus::Returned && $returnEffects
390:                 && ReturnRequest::query()->where('order_id', $order->id)->whereNotIn('status', [
391:                     ReturnStatus::Rejected->value, ReturnStatus::Cancelled->value,
392:                 ])->exists()) {
393:                 throw new BusinessException('للطلب مرتجعات قائمة؛ أكمل الاستلام والاسترداد من إدارة المرتجعات لمنع تكرار المخزون.');
394:             }
395: 
396:             // آثار المخزون بحسب الانتقال
397:             $extraNote = null;
398:             if ($to === OrderStatus::Shipped) {
399:                 $this->shipOrder($order, $actorId);
400:             } elseif ($to === OrderStatus::Cancelled
401:                 && in_array($from, [OrderStatus::Pending, OrderStatus::Confirmed, OrderStatus::Processing], true)) {
402:                 // الحجز صار من لحظة الإنشاء (F-01) فيُفك من Pending أيضًا
403:                 $this->releaseReservations($order, $actorId, 'إلغاء الطلب');
404:             } elseif ($to === OrderStatus::Returned
405:                 && in_array($from, [OrderStatus::Shipped, OrderStatus::Delivered], true)
406:                 && $returnEffects) {
407:                 // إعادة البضاعة المشحونة للمخزون بحركات sale_return (M13) —
408:                 // تُتخطى في مسار RMA لأن الاستلام الفعلي سوّاها بالفعل (مرحلة 9)
409:                 if (! $this->returnSalesToStock($order, $actorId)) {
410:                     $extraNote = 'لا توجد حركات بيع مسجلة؛ يتطلب المرتجع استلامًا يدويًا في المستودع.';
411:                 }
412:             }
413: 
414:             if ($to === OrderStatus::Cancelled) {
415:                 // عكس استخدام الكوبون حتى لا يُحرم العميل منه بإلغاء (M13)
416:                 $this->reverseCouponUsage($order);
417:                 if ($order->payment_status === 'paid') {
418:                     $order->update(['requires_refund' => true]);
419:                 }
420:             }
421: 
422:             // مرتجع لطلب مدفوع يحتاج استردادًا أيضًا، لا الإلغاء فقط (F-14) —
423:             // في مسار RMA الاسترداد اكتمل داخل طلب المرتجع نفسه فلا علم هنا
424:             if ($to === OrderStatus::Returned && $order->payment_status === 'paid' && $returnEffects) {
425:                 $order->update(['requires_refund' => true]);
426:             }
427: 
428:             if ($order->payment_method === 'wallet' && $order->payment_status === 'paid'
429:                 && ($to === OrderStatus::Cancelled || ($to === OrderStatus::Returned && $returnEffects))) {
430:                 $payment = CustomerWalletTransaction::query()->where('reference_type', 'order')->where('reference_id', $order->id)
431:                     ->where('type', 'checkout_payment')->first();
432:                 if ($payment !== null) {
433:                     app(WalletService::class)->record($payment->customer_id, -(float) $payment->amount,
434:                         'order_reversal', 'order', $order->id, $actorId);
435:                     $order->update(['payment_status' => 'refunded', 'requires_refund' => false]);
436:                 }
437:             }
438: 
439:             $order->update(['status' => $to]);
440: 
441:             // تسوية COD عند التسليم من أي مسار (أدمن يدوي أو ويب هوك) —
442:             // الأثر هنا في بوابة الحالة لا في ويب هوك الشحن فقط (F-14)
443:             if ($to === OrderStatus::Delivered
444:                 && $order->payment_method === 'cod'
445:                 && $order->payment_status !== 'paid') {
446:                 $order->update(['payment_status' => 'paid']);
447:             }
448: 
449:             // notes عمود varchar(500): ملاحظة الأدمن (حتى 500) مع الملحق قد
450:             // تتجاوزه فتنفجر بحركة إرجاع بلا حركات بيع — تُقصّ على 500 (F-28)
451:             $historyNotes = trim(($notes ?? '').($extraNote !== null ? ' — '.$extraNote : '')) ?: $notes;
452: 
453:             $order->statusHistories()->create([
454:                 'from_status' => $from,
455:                 'to_status' => $to,
456:                 'changed_by_type' => $actor?->getMorphClass(),
457:                 'changed_by_id' => $actor?->getKey(),
458:                 'notes' => $historyNotes !== null ? mb_substr($historyNotes, 0, 500) : null,
459:             ]);
460: 
461:             // التوزيع ناقص إن غاب فرع الطلب أو بقي بند بلا فرع: الاعتماد على
462:             // allocated_branch_id وحده يفشل عندما تُوزَّع البنود في فروع
463:             // مختلفة فيبقى حقل الطلب فارغًا (F1)
464:             if ($to === OrderStatus::Confirmed && ! $this->isAllocated($order)) {
465:                 $this->allocationService->allocate($order, performedBy: $actorId);
466:             }
467: 
468:             return $order->fresh(['items', 'statusHistories']);
469:         });
470:     }
471: 
472:     /**
473:      * كفاية التوزيع: يكفي أن يكون لفرع الطلب قيمة أو أن يكون كل بند موزّعًا
474:      * فعليًا في فرع ما (F1) — التوزيع الجزئي (بند بلا فرع) يُعيد الاستدعاء.
475:      */
476:     private function isAllocated(Order $order): bool
477:     {
478:         if ($order->allocated_branch_id !== null) {
479:             return true;
480:         }
481: 
482:         $distribution = $order->items()
483:             ->selectRaw('COUNT(*) AS total, COUNT(allocated_branch_id) AS allocated')
484:             ->first();
485: 
486:         if ($distribution === null || (int) $distribution->total === 0) {
487:             return false;
488:         }
489: 
490:         return (int) $distribution->total === (int) $distribution->allocated;
491:     }
492: 
493:     /** عميل جملة/توزيع معتمد — يُستثنى من سقوف التجزئة (H2). */
494:     private function isWholesaleApproved(?Customer $customer): bool
495:     {
496:         return $customer !== null
497:             && $customer->status === CustomerStatus::Approved
498:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true);
499:     }
500: 
501:     /**
502:      * توزيع مبلغ على أوزان بطريقة «أكبر باقٍ» بعدد صحيح من القروش (L5):
503:      * مجموع الحصص يساوي المبلغ بالضبط، ولا حصة سالبة بسبب التقريب.
504:      *
505:      * @param  array<int, float>  $weights
506:      * @return array<int, float>
507:      */
508:     private function distributeLargestRemainder(float $total, array $weights): array
509:     {
510:         $count = count($weights);
511:         if ($count === 0) {
512:             return [];
513:         }
514:         $totalCents = (int) round($total * 100);
515:         $weightSum = array_sum($weights);
516:         if ($totalCents <= 0 || $weightSum <= 0) {
517:             return array_fill(0, $count, 0.0);
518:         }
519: 
520:         $floorCents = [];
521:         $remainders = [];
522:         $assigned = 0;
523:         foreach ($weights as $i => $weight) {
524:             $exact = $totalCents * ((float) $weight / $weightSum);
525:             $floor = (int) floor($exact);
526:             $floorCents[$i] = $floor;
527:             $remainders[$i] = $exact - $floor;
528:             $assigned += $floor;
529:         }
530: 
531:         $left = $totalCents - $assigned;
532:         arsort($remainders);
533:         foreach (array_keys($remainders) as $i) {
534:             if ($left <= 0) {
535:                 break;
536:             }
537:             $floorCents[$i]++;
538:             $left--;
539:         }
540: 
541:         ksort($floorCents);
542: 
543:         return array_map(fn (int $cents): float => $cents / 100, $floorCents);
544:     }
545: 
546:     /**
547:      * الشحن: لكل حركة حجز — فك الحجز من reserved وخصم فعلي sale من on_hand
548:      * على نفس صف الرصيد، وزيادة عدّاد مبيعات المنتج.
549:      */
550:     private function shipOrder(Order $order, ?int $actorId): void
551:     {
552:         $reservations = $this->reserveMovements($order);
553:         if ($reservations->isEmpty()) {
554:             throw new BusinessException('لا توجد حجوزات مخزون لهذا الطلب؛ لا يمكن الشحن قبل التأكيد والتوزيع.');
555:         }
556: 
557:         foreach ($reservations as $movement) {
558:             $base = [
559:                 'product_variant_id' => $movement->product_variant_id,
560:                 'branch_id' => $movement->branch_id,
561:                 'location_id' => $movement->location_id,
562:                 'reference_type' => Order::class,
563:                 'reference_id' => $order->id,
564:                 'created_by' => $actorId,
565:             ];
566:             $this->inventoryService->recordMovement([...$base,
567:                 'type' => StockMovementType::ReleaseReserve,
568:                 'affected_bucket' => StockBucket::Reserved,
569:                 'quantity' => -1 * (float) $movement->quantity,
570:                 'notes' => "فك حجز عند شحن الطلب {$order->order_number}",
571:             ]);
572:             $this->inventoryService->recordMovement([...$base,
573:                 'type' => StockMovementType::Sale,
574:                 'affected_bucket' => StockBucket::OnHand,
575:                 'quantity' => -1 * (float) $movement->quantity,
576:                 'notes' => "بيع عند شحن الطلب {$order->order_number}",
577:             ]);
578:         }
579: 
580:         foreach ($order->items as $item) {
581:             $item->variant?->product?->increment('sales_count', (int) round((float) $item->qty));
582:         }
583:     }
584: 
585:     /** إلغاء طلب مُحجوز: فك كل حجوزاته فتعود الكميات متاحة للبيع. */
586:     private function releaseReservations(Order $order, ?int $actorId, string $reason): void
587:     {
588:         foreach ($this->reserveMovements($order) as $movement) {
589:             $this->inventoryService->recordMovement([
590:                 'product_variant_id' => $movement->product_variant_id,
591:                 'branch_id' => $movement->branch_id,
592:                 'location_id' => $movement->location_id,
593:                 'type' => StockMovementType::ReleaseReserve,
594:                 'affected_bucket' => StockBucket::Reserved,
595:                 'quantity' => -1 * (float) $movement->quantity,
596:                 'reference_type' => Order::class,
597:                 'reference_id' => $order->id,
598:                 'created_by' => $actorId,
599:                 'notes' => "{$reason} {$order->order_number}",
600:             ]);
601:         }
602:     }
603: 
604:     /**
605:      * إعادة بضاعة طلب مشحون/مُسلَّم إلى المخزون: لكل حركة بيع حركة
606:      * sale_return معاكسة على نفس الرصيد، وتنقيص عدّاد المبيعات (M13).
607:      * ترجع false إذا لم توجد حركات بيع (يحتاج استلامًا يدويًا).
608:      */
609:     private function returnSalesToStock(Order $order, ?int $actorId): bool
610:     {
611:         $sales = StockMovement::query()
612:             ->where('reference_type', $order->getMorphClass())
613:             ->where('reference_id', $order->id)
614:             ->where('type', StockMovementType::Sale)
615:             ->orderBy('id')
616:             ->get();
617:         if ($sales->isEmpty()) {
618:             return false;
619:         }
620: 
621:         foreach ($sales as $movement) {
622:             $this->inventoryService->recordMovement([
623:                 'product_variant_id' => $movement->product_variant_id,
624:                 'branch_id' => $movement->branch_id,
625:                 'location_id' => $movement->location_id,
626:                 'type' => StockMovementType::SaleReturn,
627:                 'affected_bucket' => StockBucket::OnHand,
628:                 'quantity' => -1 * (float) $movement->quantity,
629:                 'reference_type' => Order::class,
630:                 'reference_id' => $order->id,
631:                 'created_by' => $actorId,
632:                 'notes' => "مرتجع مبيعات للطلب {$order->order_number}",
633:             ]);
634:         }
635: 
636:         foreach ($order->items as $item) {
637:             $product = $item->variant?->product;
638:             if ($product !== null) {
639:                 $product->update(['sales_count' => max(0, (int) $product->sales_count - (int) round((float) $item->qty))]);
640:             }
641:         }
642: 
643:         return true;
644:     }
645: 
646:     /** عكس تسجيل استخدام الكوبون عند إلغاء الطلب: حذف السجل وإنقاص العدّاد (M13). */
647:     private function reverseCouponUsage(Order $order): void
648:     {
649:         foreach (CouponUsage::query()->where('order_id', $order->id)->get() as $usage) {
650:             Coupon::query()->whereKey($usage->coupon_id)->where('used_count', '>', 0)->decrement('used_count');
651:             $usage->delete();
652:         }
653:     }
654: 
655:     /** حركات الحجز الأصلية للطلب من الدفتر (مصدر الحقيقة لمواضع الحجز ومواقعه). */
656:     private function reserveMovements(Order $order): Collection
657:     {
658:         return StockMovement::query()
659:             ->where('reference_type', $order->getMorphClass())
660:             ->where('reference_id', $order->id)
661:             ->where('type', StockMovementType::Reserve)
662:             ->orderBy('id')
663:             ->get();
664:     }
665: 
666:     // التخزين على مستوى الـ instance لا static (F-27): في Octane/العمال
667:     // طويلة العمر كانت قيمة static تبقى عالقة بين الطلبات وبين الاختبارات
668:     private ?int $systemActorId = null;
669: 
670:     private bool $systemActorResolved = false;
671: 
672:     /**
673:      * منفّذ حركات المخزون: الموظف الفاعل نفسه؛ وعند غيابه (عميل/ويب هوك)
674:      * يُنسب التنفيذ لمستخدم النظام المخصص (M19) — لا لأول Super Admin،
675:      * حتى يبقى سجل التدقيق صادقًا. يُحسم مرة واحدة لكل نسخة خدمة.
676:      */
677:     private function inventoryActorId(?Model $actor): ?int
678:     {
679:         if ($actor instanceof User) {
680:             return (int) $actor->getKey();
681:         }
682: 
683:         if (! $this->systemActorResolved) {
684:             $this->systemActorResolved = true;
685:             $systemId = User::query()
686:                 ->where('email', (string) config('orders.system_user_email', 'system@alfarid.local'))
687:                 ->value('id');
688:             $this->systemActorId = $systemId !== null ? (int) $systemId : null;
689:         }
690:         if ($this->systemActorId !== null) {
691:             return $this->systemActorId;
692:         }
693: 
694:         // رجوع احتياطي إن لم تُزرع هجرة مستخدم النظام بعد
695:         $adminId = User::query()
696:             ->whereHas('roles', fn ($q) => $q->where('name', 'Super Admin'))
697:             ->orderBy('id')
698:             ->value('id');
699: 
700:         return $adminId !== null ? (int) $adminId : (auth()->user() instanceof User ? (int) auth()->id() : null);
